/* 2001年6月5日 区民委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h13-20010605-6","dateIso":"2001-06-05","title":"2001年6月5日 区民委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2296#one","fetchedAt":"2026-08-14","characters":68784,"voices":[{"i":1,"speaker":"南委員長","text":"○午後１時０５分開会\nただいまから区民委員会を開会いたします。\n今日の予定は、皆さんのお手元に配付してあります予定表のとおりであります。どうぞよろしくお願いいたします。\n────────────────────────────────────────────\n１．幹部職員紹介"},{"i":2,"speaker":"南委員長","text":"一番最初に、幹部職員の紹介を議題といたします。\n５月２５日の委員会で、区民生活事業部、環境清掃事業部の両部長の自己紹介がありましたけれども、実質的に今回が初めての委員会ですので、改めて委員、理事者相互の自己紹介をお願いしたいと思います。\nまず、私から初めに行わせていただきます。今年１年、委員長を務めます南でございます。どうぞよろしくお願いいたします。"},{"i":3,"speaker":"石田副委員長","text":"石田でございます。今年１年間副委員長を務めさせていただきます。委員長を支えて一生懸命やっていきたいと思います。どうぞよろしくお願いいたします。"},{"i":4,"speaker":"原委員","text":"自民党の原でございます。区民委員会は初めてでございます。しっかりやりたいと思います。よろしくお願いいたします。"},{"i":5,"speaker":"金高委員","text":"民主党区民連合の金高でございます。同じく初めてでございますので、すべてが初めてでございます。よろしくお願いいたします。"},{"i":6,"speaker":"藤原委員","text":"区民クラブの藤原です。よろしくお願いいたします。"},{"i":7,"speaker":"堺委員","text":"公明党の堺でございます。よろしくお願いいたします。"},{"i":8,"speaker":"菊地委員","text":"共産党の菊地でございます。よろしくお願いいたします。"},{"i":9,"speaker":"本田委員","text":"合同の本田です。昨年に引き続きよろしくお願いします。"},{"i":10,"speaker":"宮地区民課長","text":"それでは、区民生活事業部の各課長についてご紹介いたします。\n本日、事業部長の小栗部長が欠席のため、私のほうからご紹介をさせていただきます。\n私は、区民課長をしております宮地と申します。どうぞよろしくお願いいたします。\nそれでは、行政順にご紹介いたします。\n地域活動課長をしております長田でございます。"},{"i":11,"speaker":"長田地域活動課長","text":"長田でございます。よろしくお願いいたします。"},{"i":12,"speaker":"宮地区民課長","text":"続きまして、防災課長をしております辻田課長でございます。"},{"i":13,"speaker":"辻田防災課長","text":"辻田です。よろしくお願いいたします。"},{"i":14,"speaker":"宮地区民課長","text":"産業振興課長をしております市川課長でございます。"},{"i":15,"speaker":"市川産業振興課長","text":"市川でございます。よろしくお願いいたします。"},{"i":16,"speaker":"宮地区民課長","text":"戸籍住民課長をしております冨田課長でございます。"},{"i":17,"speaker":"冨田戸籍住民課長","text":"冨田でございます。よろしくお願い申し上げます。"},{"i":18,"speaker":"宮地区民課長","text":"税務課長をしております松崎課長でございます。"},{"i":19,"speaker":"松崎税務課長","text":"松崎でございます。よろしくお願いいたします。"},{"i":20,"speaker":"宮地区民課長","text":"徴収推進担当をしております蓼沼担当課長でございます。"},{"i":21,"speaker":"蓼沼徴収推進担当課長","text":"蓼沼でございます。よろしくお願いいたします。"},{"i":22,"speaker":"宮地区民課長","text":"保険年金課長をしております太田課長でございます。"},{"i":23,"speaker":"太田保険年金課長","text":"太田でございます。よろしくお願いいたします。"},{"i":24,"speaker":"宮地区民課長","text":"年金制度担当の小野担当課長でございます。"},{"i":25,"speaker":"小野年金制度担当課長","text":"小野でございます。よろしくお願いいたします。"},{"i":26,"speaker":"宮地区民課長","text":"今度から窓口１本化ということで、品川文化振興事業団が区民生活事業部のほうに位置付けられておりまして、管理課長をしております上山課長でございます。"},{"i":27,"speaker":"上山総務部副参事","text":"上山でございます。よろしくお願いいたします。"},{"i":28,"speaker":"宮地区民課長","text":"同じく文化振興課長の志村課長でございます。"},{"i":29,"speaker":"志村総務部副参事","text":"志村でございます。よろしくお願いいたします。"},{"i":30,"speaker":"宮地区民課長","text":"以上でございます。"},{"i":31,"speaker":"野本環境清掃事業部長","text":"それでは、環境清掃事業部の幹部職員をご紹介させていただきます。\nまず、私の隣が金井環境課長でございます。"},{"i":32,"speaker":"金井環境課長","text":"金井でございます。どうぞよろしくお願いいたします。"},{"i":33,"speaker":"野本環境清掃事業部長","text":"その隣が清掃リサイクル課長の中山でございます。"},{"i":34,"speaker":"中山清掃リサイクル課長","text":"中山でございます。よろしくお願いいたします。"},{"i":35,"speaker":"野本環境清掃事業部長","text":"金井課長のうしろが、清掃事業調整担当課長の東でございます。"},{"i":36,"speaker":"東清掃事業調整担当課長","text":"東でございます。よろしくお願いします。"},{"i":37,"speaker":"野本環境清掃事業部長","text":"その隣がＩＳＯ担当の宍戸でございます。"},{"i":38,"speaker":"宍戸ＩＳＯ担当課長","text":"宍戸でございます。よろしくお願いいたします。"},{"i":39,"speaker":"野本環境清掃事業部長","text":"最後列になりますけれども、品川清掃事務所長の山口でございます。"},{"i":40,"speaker":"山口品川清掃事務所長","text":"山口でございます。よろしくお願いいたします。"},{"i":41,"speaker":"野本環境清掃事業部長","text":"その隣が荏原清掃事務所長の後藤でございます。"},{"i":42,"speaker":"後藤荏原清掃事務所長","text":"後藤でございます。よろしくお願いいたします。"},{"i":43,"speaker":"野本環境清掃事業部長","text":"最後になりましたけれども、環境清掃部長をやらせていただいております野本と申します。どうぞよろしくお願いいたします。"},{"i":44,"speaker":"南委員長","text":"それぞれありがとうございました。\n今年１年、このメンバーでしっかりと委員会活動を行っていきたいと思いますので、よろしくお願いいたします。\nそれから、この委員会の書記は、多田書記と、小泉書記が担当しますので、どうぞよろしくお願いいたします。"},{"i":45,"speaker":"事務局","text":"多田でございます。よろしくお願いいたします。"},{"i":46,"speaker":"事務局","text":"小泉でございます。よろしくお願いいたします。\n────────────────────────────────────────────\n２．事務事業概要"},{"i":47,"speaker":"南委員長","text":"それでは、事務事業概要の説明に入っていきたいと思います。\n進め方につきましては、予定表のとおりに、まず初めに、区民生活事業部、その次に環境清掃事業部というふうに分けて、それぞれのセクションで一括して説明をしていただきたいと思います。\nかなり膨大な範囲ですので、しっかり受け止めていきたいと思っておりますが、しかし、ポイントを絞っていただいて、こうだというところをちょっと強調して説明をしていただければありがたいところです。また、具体的な質疑については、説明が終わった後に行っていただきたいと思いますので、それぞれ委員の方よろしくお願いいたします。\nそれでは、まず初めに、区民生活事業部の説明をお願いします。"},{"i":48,"speaker":"宮地区民課長","text":"それでは、総括説明および区民課の事務事業概要ということで、一括してご説明をさせていただきます。\nまず、事務事業概要、ちょっと厚くなっております、こちらのほうをご覧いただきたいと思います。表紙をおめくりいただきますと、組織全体の図がございます。区民生活事業部ですが、今回の組織改正で、地域活動の育成や、地域の防災対策確立など、地域コミュニティの推進に係わる部門と、戸籍、税、国保、年金など、行政窓口部門を統合しまして、日常の区民生活全般にわたるサービスの向上を図る部門といたしました。\nまた、臨海部広域斎場建設事務や、本年度から企画が所管していましたメイプルセンターも含めた品川文化振興事業団の窓口を本事業部に１本化いたしまして、職員数総勢４２７名の組織となっております。\n総括につきましては、以上で終わらせていただきます。\n次に、区民課の事務事業概要に入らせていただきたいと思います。間に黄緑色の紙が入ってございます。区民課でございますが、１ページのところに事務分掌がございます。区民課は庶務係を初め、消費者センター、統計、市町村交流の４係を所管している課でございます。\n２ページは庶務係の部分でございますが、主な事業といたしましては、２ページから４ページまであります区民保養施設に関する事業がございます。２ページは品川荘でございますが、昭和３４年に開荘いたしまして、途中で、平成８年に一旦改築、改装いたしまして、一時お休みさせていただきましたが、引き続き人気のある施設でございます。こちらは部屋数１５室、利用定員７３名となっておりまして、実績については表のとおりでございます。\n後ほどご説明いたしますが、全体の受付業務を一体化しまして、ＯＡ機器による利用の予約、それから清算払いということでは、直接現地で、ホテルと同じようにチェックアウトのときにお金を払っていただければいいような形に変えておりますので、ここら辺がまた利用しやすくなった点でございます。\nそれから、３ページでございますが、こちらは委託保養施設という形で書いておりますが、具体的な名称は暖景苑でございます。暖景苑、民間施設を全面的に借り上げまして宿泊施設としているものでございます。こちらのほうは１３室で、４７人の定員ということでございます。利用状況は、下のほうに施行実績がございますが、後ほどご覧いただければと思います。\n４ページは箱根荘の管理運営事務でございます。こちらは平成１０年に開荘となっておりまして、それまでは箱根林間学園という形で、校外施設として使われていたものでございます。近年人気が出てきてございまして、執行実績にもございますように、年々利用者数が増えているところでございます。\n次に、５ページ、６ページは、区民の斎場関係のところとなってございます。４の区民斎場というのは、なぎさ会館ということでございまして、こちらのほうはよく利用されて、ご承知かと思いますが、利用料金は６万5,０００円となっておりまして、こちらにございますようなのが執行実績となってございます。\nそれから、６ページの平塚橋会館でございますが、こちらのほうは区民集会所もあわせて使えるような形になっておりまして、斎場といたしましては、骨葬の形で斎場ができているということでございます。だんだんＰＲも進んできまして、利用も少しずつ増えてきたところでございます。７ページに利用の状況が出てございますが、平成１１年度より平成１２年度という形で、利用率も上がってございます。\n次に、９ページは、奨学金貸付事務でございますが、これもかなり古くからの皆さんのための事業でございます。特に修学する意志があっても、経済的な理由で高等学校あるいは専門学校、専修学校等に修学が困難な方たちに対しまして、必要な奨学金を貸し付ける制度でございます。公立、私立、専修学校、それぞれ入学準備金、在学資金という形で奨学金を出してございます。\n１０ページは、保養施設の受付ということで、先ほどお話しした内容のとおりでございます。\n１１ページは、臨海部広域斎場建設事務でございます。こちらにつきましては、一部事務組合方式をとっておりまして、品川区を初め大田区、世田谷区、目黒区、港区ということで、５区で形成する地方自治法上の一部事務組合をつくってございます。\n場所といたしましては、大田区東海１丁目３番で、敷地２万2,５００m2ございます。予定している施設内容といたしましては、火葬炉８基を予定しておりますが、後々の増設ができるような形で余裕を持って設計をしているところでございます。\nスケジュールといたしましては、現在実施設計に着手しておりますが、平成１３年度中に実施設計が完了いたしまして、平成１４年、平成１５年度で建設工事、平成１６年度に開場の予定でございます。\n１２ページは、消費者センター、消費者行政の体系と施策ということで網羅してございますが、特に自立する消費者の育成という形では、組織化をしております消費者団体連絡会への支援というところに特に力を入れております。\nこの場をお借りしまして何ですが、６月１２日に消費者団体連絡会がございます。既に委員の皆様にご通知を差し上げているところでございますが、ぜひともご参加くださいますよう、よろしくお願い申し上げます。\nそれから、消費者全体の生活環境改善ということでは、生活物資の監視や指導、それから、物を大事にするという１つの普及啓発の意味でも、おもちゃの病院というのをボランティアの方にお願いして、毎週土曜日にやってございます。\nそれから、もう一つ大事な柱でございます消費者保護ということで、消費生活相談というのを消費者センターで実施しております。これが１２ページにある体系でございまして、特に個別な説明は省略させていただきますが、先ほどの消費者相談につきましては、１６ページにございますので、１６ページをお開きください。\nこちらでは、相談の執行実績というのがございまして、相談そのものは平成１１年度から平成１２年度に向けて件数が増えてございます。\nその内訳が１７ページにございますが、平成８年度から平成１２年度で上位の順位をとってみましたけれども、特に平成１２年度はサラ金関係、賃貸アパート関係、エステティックサロンのことによる契約関係、リースサービス、クリーニングといったところが上位を占めてございました。\nまた、今年度から、ここには触れてありませんが、消費者契約法というのが４月１日から施行されております。その関係で、また相談等が増えるのではないかということで、普及啓発、相談体制などの充実をさせていただいているところでございます。\n続きまして、２２ページは統計係が所管する各種統計の事務でございます。こちらのほうは、統計法に基づく統計ということで、指定統計になっておりまして、本年度は特に大きいところが、５年ごとに実施します、２２ページの(4)ですが、事業所・企業統計調査を行っております。これは今年１０月１日を調査期日といたしまして、登録調査員の方に協力をしていただきながら、全体的な対象といたしまして、家事サービス業、外国公務を除く全産業の事業所を対象として統計をとるという事務でございます。\n２４ページは、今お話ししました統計調査員を確保するためのいろいろな対策事業をやってございます。\n２５ページは水と緑の市町村との交流事業ということで、皆様ご承知かと思いますが、品川区では山北町、それから、山梨県の早川町と水と緑のふれあい交流協定を結びまして交流をしているところでございます。\n２６ページには山北町との交流の実績が載っておりますが、ここのところでちょっと低迷しておりましたけれども、平成１２年度でまたかなり交流規模が増えてきてまいりまして、引き続きＰＲに努めてまいりたいというふうに考えております。\n２７ページは、早川町との交流で、こちらのほうは２８ページに執行実績が載ってございます。平成１１年度から平成１２年度にかけて、こちらのほうもＰＲをし、交流人数が増えてございます。\n最後になりましたが、２９ページ、総合区民会館運営事務がございます。これは品川区立総合区民会館条例に基づきまして、管理委託を品川文化振興事業団に委託をしているところでございまして、内容につきましては、施設の内容、利用実績等がその後ずっと続いてございますので、お目通しいただければと思います。\n区民課の事務事業は、以上でございます。"},{"i":49,"speaker":"長田地域活動課長","text":"それでは、引き続きまして、地域活動課に関係する事務事業の説明をさせていただきます。\n地域活動課は２係２担当主査および１３の地域センターで構成をされておりまして、１２２名の職員で仕事を遂行しているところでございます。\n平成１２年４月１日に旧出張所の見直しによりまして１年２カ月ほど経ったわけでございますけれども、現在は窓口業務の充実とともに、地域にも目を向けようということで、職員一同頑張っているところでございます。\n各係の所掌事務につきましては、１ページ、２ページに記されているとおりでございます。\n３ページから、町会・自治会関連事業でございますけれども、１番、区政協力委員会経費でございます。区民意識、区民の要望等を正確に反映して、区政を効率的に推進するため、現在２０５名の区政協力員を置いているところでございます。\n春の区政協力委員会協議会、それから、ブロックごとの区政協力委員会、秋には各地区ごとの区政協力委員会を実施をしているところでございます。実績につきましては、下の表のとおりでございます。\n４ページは、地域振興事業でございます。(1)品川区町会連合会補助金等でございますけれども、町会連合会が行います会議、研修、調査研究、保険の加入等々、こういった部分の補助金を支出をして、町会活動がうまくいくような形で支援をさせていただいているところでございます。\n５ページは町会法人化事務でございます。平成３年に地方自治法が改正されまして、町会名義で財産の取得ができるというようなことになりまして、平成１２年度末現在で３４町会が法人化の手続きを終えたところでございます。当然、その３４町会にとっては、町会会館等を町会名義で所有をするという形になってございます。\n６ページが地域センター管内別区施設連絡会でございます。地域にはいろいろな会議がふくそうをするということで、できるだけそういった日程の調整を行っていこうという目的を持って行われているものでございます。会議、行事予定表の発行ですとか、あるいは地域センターごとに地域情報紙、月間情報ニュースを毎月発行をしているところでございます。\n７ページ、地域ニュース発行事務でございますけれども、これはコミュニティ情報紙として、各地域センターごとに、大体年４回が多うございますけれども、それぞれの地域センターによっていろいろなお知らせですとか、事業の紹介、地域の出来事についてお知らせをしているところでございます。\n８ページ、地域振興事業でございます。地域の問題が地域で解決をできるようにということで、自治会連合会の会長に地域振興事業を委託をしているところでございます。受託をした各地区におきましては、地区活動会議を開催をして、その地域に起こるさまざまな問題を調整をしているところでございます。\n９ページ、地域環境整備等助成金でございますけれども、区のほうで交通安全、町内美化、緑化推進、障害者、高齢者等の福祉の増進、こういったもろもろの事業についてやっていただいている部分がございます。こうした裏付けといたしまして、１町会当たり平均２６万円強の補助金を出して、この事業の推進に努めているところでございます。\nそれとは別に、環境整備特別ということがございまして、大井競馬場周辺の環境を整備するために、大井第一地区と大井第二地区の町会にはそれぞれ別枠で補助金を交付しているところでございます。\n次、１０ページ、地域活動基盤整備補助でございます。この事業につきましては、(1)各町会・自治会が自らの会館を建設をするとき、あるいは改修をするときの経費の補助、それから、１１ページでございますけれども、その会館が葬祭ができるような場合につきましては、その葬祭に必要な設備の助成、それから、１２ページでございますけれども、町会・自治会館の登記費用の一部を助成しているところでございます。\n１３ページでございます。従来から町会独自の掲示板を持ってございましたけれども、この掲示板を町会がつくるときに一定の割合で助成もしております。\nそれから、14ページからは防犯、防火の関係でございます。まず防犯協会への補助金でございますけれども、各協会が防犯意識の高揚ですとか、防犯思想の普及、さまざまな活動を行ってございます。こうしたことに対しまして、区からその経費の一部を助成するというようなことで、防犯思想の高揚に努めているところでございます。\nその一環でございますけれども、秋には地域安全の集いということで、警察と、各防犯協会、品川区、三者合同で集いを開催しておりますけれども、それの経費の一部を助成してございます。\n１５ページにつきましては、防火協会への補助金でございます。防犯協会と同じで、防火に関するさまざまな普及、ＰＲ、こういった経費の一部を助成してございます。\n次に、１６ページから区民まつりでございます。区民まつりにつきましては、地域のふれあい、最近では参加とふれあいということをキャッチフレーズに各地区で実施をしているところでございますけれども、平成１２年度につきましては１２地区、６万6,０００余りの参加をいただきまして盛大に行われたところでございます。なお、去年は大井第二地区がおまつりをできなかったんですけれども、今年についてはやっていただけるということで、１３地区になる予定でございます。\n各地区の実績につきましては、下の表のとおりでございます。\n１８ページ、地域美化推進経費ということで、(1)ポイ捨て禁止条例の普及と啓発経費ということで、平成９年に条例ができまして、この条例の普及と啓発を図って、快適で安全な住みよい地域社会の形成をしていこうということで、さまざまなＰＲ活動等をやってございます。６月３日に環境リサイクルフェアへ参加をいたしまして、ＰＲをさせていただいたところでございます。\nそのほかにも、立会川の浄化、あるいは条例施行記念啓発活動ということで、今年は武蔵小山で行いますけれども、こういった事業に合わせまして条例の普及を図っていこうというものでございます。\n次のページ、吸い殻入れ・ごみ箱につきましては、ポイ捨てをされないように、できるだけごみ箱、吸い殻入れを整備をいたしまして、ごみを捨てない、出さないというようなことで、清掃を行っているものでございます。\n１９ページの真ん中ぐらいですけれども、地域美化推進経費ということで、この部分につきましても、１３地区の連合町会がさまざまな形で地域美化に協力をしていただいております。それの経費の一部を助成をすることによって、環境美化の推進を図っていくというようなことで実施をしております。\n実績につきましては、２０ページのとおりでございます。\n２１ページ、ふれあい掲示板でございます。従来、区の掲示板だったものでございますけれども、平成４年からコミュニティ掲示板ということで、町会に開放をしてきました。また、そのポスターの掲出等の整理についても町会に依頼をしているところでございます。現在、４８５本の掲示板の維持管理を行ってございます。\n２２ページからが青少年関連事業でございます。まず、青少年問題協議会でございますけれども、青少年関係の総合的な調整を図るために、青少年問題協議会を置いてございます。この中で区内さまざまな問題の協議を諮り、それの協議内容を各団体が持ち帰っていただいて、それぞれの立場で事業を実施をしていただくという形になってございます。\nこれとは別に、専門部会が３つございまして、基本方針の作成、夏季対策の作成、健全育成冊子の作成、こういった専門部会の活動のほかに、こども１１０番ですとか、青少年対策の概要等を発行してございます。\n２３ページ、青少年健全育成事業でございますけれども、(1)明るい家庭づくりでございます。品川区の場合は、毎月第１日曜日を家庭の日と定めて、親子がふれあう事業として位置付け、さまざまな事業を実施しているところでございます。\n家庭は青少年の人格を形成する上で最も重要な場であるというようなことで、それぞれの地区も、家庭挙げまして親と子のふれあいの充実をしているよう心がけているところでございます。\n２４ページにつきましては、地区委員会事業でございます。それぞれ１３地区ごとに地区委員会が構成をされてございますので、そのさまざまな各地区の実態に合った事業展開を実施をしてございますけれども、その費用の一部を助成をしてございます。\n２５ページ、連合会委託事業でございますけれども、区全域で進めるべき事業、あるいは各地区の交流を目的に連合会が形成されておりますけれども、その連合会で健全育成講演会ですとか、宿泊研修会等々実施をしているものでございます。\n次の２６ページへいきまして、4)でございます。コミュニティスクール、これは毎回講師をお招きをして実施をしている講演会でございますけれども、平成１２年度につきましては、サッカー協会の岡野俊一郎さんをお迎えをいたしました。大変心に残ったとの評判の声をいただいているところでございます。\nその下の、中学生の主張大会でございますけれども、１２年度に初めて実施をした事業でございます。地域の事業に中学生の参加が少ないというようなことで、ぜひ中学生の意見を聞いた上で、今後の事業展開をしていこうということで始めまして、大変好評をいただいたところでございます。本年度以降も継続をしていく予定でございます。\nその下、２６ページでございますけれども、青少年の健全育成公演会、これが平成１３年度の新規事業でございます。宝くじの助成を受けまして、覚せい剤等薬物乱用の問題がかなり身近にあるわけでございますけれども、演劇をやることによりまして、薬物の怖さを認識をさせて、その未然の防止を図ろうとするものでございます。\nそれから、次飛びまして、２８ページからが地域の住民同士の助け合いでございます。地域相互支援事業、これにつきましては、地域で何らかの手助けを必要としている人に対して、その地域の人がお手伝いをして差し上げる。その調整につきましては、地域センターがコーディネート役になるというようなことで進めてございます。\nその下、地域食事サービスでございますけれども、小学校でつくった昼食、中学校でつくった夕食、ボランティアがつくった給食をそれぞれ週２回、該当のお宅に届けているところでございます。\n飛んでいただきまして、３０ページからの事業につきましては、平成１３年度の組織改正によりまして、障害者福祉課から移管をされた事務でございます。まず、災害応急対策事業でございますけれども、区内での火災ですとか水害、こういったものに見舞金、あるいは亡くなった場合は弔慰金、見舞品等を支給をしていくというようなことが新たに地域活動課の事務として加わったものでございます。\n３１ページが日本赤十字社の事業でございます。毎年５月の赤十字社員増強運動、これは目標額に対しまして１４０％の達成率でございますけれども、町会の方々には大変お世話になっている事業でございます。\nそのほか災害救援金品等の支給も行ってございます。\n３２ページは共同募金事業、毎年１０月に共同募金が行われますけれども、そちらの募金の集金等も町会にお願いをして実施をしていただいております。こちらのほうも達成率１５４％ということで、品川区はずっと好成績を残しているところでございます。\n３３ページ以降につきましては、関連資料ということで、後ほどお目通しをいただければと思います。\n地域活動課の事業につきましては、以上でございます。"},{"i":50,"speaker":"辻田防災課長","text":"引き続きまして、防災課の事務事業をご説明いたします。\nまず、１ページをお開けいただきたいと思います。事務分掌として、計画係と普及係、２係で、職員１０名、再雇用職員６名ということで、１６名体制で実施しております。\n以前は防災センター担当というのがございましたけれども、普及係のほうに統合しております。\n２ページ、防災会議ということで、基本的な防災計画を決める会議でございます。平成１０年に改正をし、２年経っておりますので、今年はもうちょっと見直しをしなければならない状況になっております。\n３ページ、防災体制整備です。応急活動を速やかに行うため区の体制を整備するということで、ここでは４ページの下のほうを見ていただきたいと思います。昨年の被害状況が出ております。平成１２年度応急対策本部を設置しましたのは３回でございます。被害も少なくて、大変良かったという年でございます。ただ、７月の梅雨の半ばに集中しているということでございまして、私どももこれから梅雨を迎えるに当たって大変緊張をしている状況でございます。\n次、５ページでございます。消防団に対する補助等がこの中に書かれております。\n６ページ、学校等の避難所機能の充実を図るということで、各種整備がなされております。\n倉庫の改修、大釜、ゴトクの配備というのはすべて終わりました。それと同時に、ソフト部分で避難所の運営をスムーズに運営していくために、連絡会議の開催であるとか、避難所訓練の実施などもしております。\nそれから、以前、防災倉庫にありましたいろいろな備蓄品につきまして、分散配付ということで、下のほうにいろいろなものが備蓄してある内容が書かれております。今後この部分につきましては、分散配備ということで、これから充実させていこうということで考えております。\n７ページの下のほう、備蓄物資の整備ということでございます。ここに倉庫がずっと書いてございますけれども、分散いたしましたので、学校のほうに大分いろいろなものが入っております。空いている部分につきましては、何かあったときにいろいろな物資が運び込めるようなということで少し空けている部分、そういう体制をとっております。\n９ページでございます。街頭消火器の整備、これは開発指導要項等により、大きなマンションなどを建てるときは必ず設置義務を付けておりますので、毎年約１００本ずつぐらい増えているということで、これはまちの安全に非常に寄与しているという具合に考えております。\n給水施設の管理、これは飲料水の部分でございます。\n１１ページは防災活動広場の維持ということで、計画は２９カ所になっております。現在２０カ所ということですけれども、なかなか適地が見つからないというのが現状でございます。できれば、非常に不燃度の高いところに３００m2以上の土地が確保できれば最適であるということで探しておりますけれども、なかなかないというのが現状でございます。\nその裏付けとなるものが、１３ページの１１番に買収計画が書かれております。\n１３ページの下、貯水槽の整備でございます。これは防火用水でございます。品川区は開発指導要項で徹底的に皆さんに設置義務を付けてお願いしておりますので、かなりの数のものが設置されてきているということです。これも地域の安全や向上させるために大きく寄与しているということでございます。\n現在私どものほうが力を入れておりますのは、普及係の防災区民組織の育成ということでございます。地域のコミュニティをより豊かにする中で、自助、自らを助ける、それから共助、お互いに助け合うというようなことを促進しておりますけれども、その基本となるのが防災区民組織の育成でございます。\nその次、１５ページは防災協議会ということで、防災区民組織のいろいろな形での連絡、それから、地域の事業所や商店街が一体となった災害に強いまちづくりのために防災協議会を開いております。\n次に、１６ページの、防災訓練でございます。これは職員の訓練等もこの中に書かれております。訓練概要の真ん中辺に、風水害初動活動態勢訓練、平成１２年は６月７日実施ということでございまして、実を言いますと、本日、抜き打ちの部分を実施いたしました。これは後でご説明いたします。\nそれから、９月の職員防災訓練もこの部分に入っております。\n防災普及教育ということで、各所に起震車を出して、体験してもらうという事業を実施しております。\n災害弱者の安全確保ということで、これにつきましては、お互いに助け合うというようなことで、地域の中で高齢者であるとか、障害を持っている方につきまして、助けていただきたいという、そういうシステムづくりを現在やっているところです。\n１９ページ、展示・体験施設、これは品川シアターにございます。この部分につきましても、今年は積極的に地域の方々を呼び込むような形での事業を実施していくというので、今検討をしているところでございます。\n雑ぱくでございますが、防災課の概要につきましては、以上でございます。"},{"i":51,"speaker":"市川産業振興課長","text":"産業振興課の目次のところをお開きいただきたいと思います。目次、両面にわたりまして、全部で３３の事業がございます。資料自体が５０ページを超しておりますので、先ほど委員長からもお話がございましたが、主要事業あるいは新規の事業ということにピックアップいたしまして説明をさせていただきますことを、あらかじめご了解いただきたいと思います。\n１ページをお願いいたします。産業振興課の組織分掌でございますけれども、私ども４つの係、１９人の職員と１１人の非常勤職員、商工相談員でございますけれども、そういった構成になってございます。\nなお、私どもの産業振興課の事業予算の関係で概略説明申し上げますと、平成１３年度の事業予算はおよそ９億５００万円となってございます。前年度の７億4,５００万円に比べて２２％の増となってございます。そのほか中小企業事業資金融資あっ斡の基金など１３億5,６００万円ほどが基金として持ってございます。\n２ページをお願いいたします。２ページから１０ページまでが勤労者福祉関連事業という事業がグループとなってございます。中小企業センターの運営でございますが、中小企業センター維持管理、施設設備の貸し出しを行ってございます。実績については、３ページのとおりでございます。\nなお、中小企業センターの２階には産業振興課の事務所、４階には東京商工会議所品川支部など、産業関係団体の事務所がテナントとして入ってございます。\nしばらくページを飛ばしまして、１０ページをお願いいたします。６番目の伝統的産業の振興でございます。この事業につきましては、品川区伝統工芸保存会の協力をいただきまして、センター１階の常設展示場で毎月実演を行ってございます。特に最近、小学生の授業としての見学が増えてございます。また、小学校へ保存会の会員を派遣いたしまして、伝統工芸ふれあい教室を実施してございます。さらに、毎年１月、恒例になりましたが、きゅりあんのイベントホールにおきまして、「伝統の技と味／しながわ」展などを実施してございます。\n１１ページから１８ページまでは、経営相談の関連事業ということでまとめてございます。１１ページにございます、情報収集提供事業でございますが、主たる事業といたしましては、しながわ産業ニュースを年６回発行してございます。区内２万9,０００の事業所に直接お届けをして、各種の助成事業の案内、あるいは中小企業センターの施設利用の案内などを行ってございます。\n次に、１４ページから１６ページまで、中小企業事業資金融資あっ斡事業でございます。区内の中小企業者の事業資金の調達を容易にするとともに、利子補給によりまして低利の融資、あるいは信用保証料の補助によって事業者の負担の軽減を図ってございます。\n本年度の特徴を何点か申し上げます。本年度の新規の融資枠といたしましては、４２億円を予定してございます。ちなみに、昨年度は３３億円という新規融資枠を想定してございましたが、実際の融資実績は６３億円ということになってございます。先般の第１回定例会で一部制度の改正を行ってございます。事業設備資金の返済期間を５年から７年に延長いたしました。併せて小規模企業特別事業資金、俗に小特資金と言ってございますが、これも４年から５年に期間延長をいたしました。また、これらの制度改正に合わせまして、本年度、従来の信用保証料の補助金の申請手続きをより簡便なものにいたしまして、基本的にご利用なさるお客さんは１回の来庁ですべてが済むというように改善をいたしてございます。\n次に、１８ページの経営カレッジでございますが、この事業は、従来、品川産業コミュニティカレッジということで、事業経営とか、企業実務に必要な各種講座を実施してまいりましたが、従来の事業の内容を見直し、新たに組み直ししてスタートをするものでございます。\n次に、１９ページから２９ページまでが商業振興対策事業のグループになってございます。助成事業が主たる内容でございますが、幾つか特徴的な助成事業を説明させていただきます。\nまず、２１ページでございますが、チャレンジマート事業、この事業は商店街の空洞化に対する歯止め策ということで、空き店舗対策事業として取り組んでいるものでございます。\n次に、２２ページ、２３ページは商店街にぎわい創出事業でございます。今年度イベント助成につきましては、１１団体、これは既に指定をいたしてございます。また、例月の販促事業に対する助成でございますにぎわい助成事業については、２２件、商店街の数に直しますと、２９の商店街を今年度既に指定してございます。\n今年度の新しい取り組みといたしまして、２３ページの一番上にございますが、区内一斉売出しの広告宣伝費の助成というものがございます。年に４回、区商連が中心になりまして、今年度は第１回が６月３０日の土曜日、今後、１０月、１２月、来年の３月、この４回、区内の商店街に呼びかけをいたしまして一斉売出しを実施いたしますが、その際、当日の朝、区内の全世帯に向けて４大紙の折り込みチラシ、広域チラシをつくる、そのことに対する助成措置でございます。\n次に、２４ページ、２５ページは商店街活性化推進事業ということで、本年度はポイントカードの導入、これは、青物横丁商店街でございます。また、武蔵小山商店街のアーケード照明設備の改修、もう一つは、戸越銀座商店街連合会、戸越銀座の３つの商店街が連合でインターネットの活用ということでハード事業、ソフト事業に対する助成金、総額6,３００万円の事業を予定してございます。\n次に、２９ページをお願いいたします。今年度の新規事業でございます。小規模商店街活力づくり支援事業ということで、先ほど説明をいたしました、にぎわい創出事業、あるいは説明を省かせていただきましたが、元気を出せ商店街事業、これらの助成事業に参加できない、いわゆる小規模商店街の活性を図るために、地域的な顧客サービスの展開など種々の支援を行っていこうとするものでございます。\n次に、３０ページからが工業振興対策事業でございます。３０ページ、３１ページは、企業間交流支援事業ということで、異業種交流活動グループ等への支援を行っているものでございます。\n事業実績については、示してあるとおりでございます。\n次に、今年度の新規事業でございますが、４０ページをお願いいたします。企業活力づくり支援事業ということで、経営革新や、新分野進出といったものに向けて意欲的な事業展開をする中小製造業に対して、専門コンサルタントの長期派遣など、経営課題に即した継続的な支援を行っていく、そういったことを内容にしてございます。\nさらに、４１ページ、ベンチャー創業支援事業、これも今年度の新規事業でございます。区内製造業の活性化に有効と思われるベンチャー型企業の創業を支援することによりまして、品川区の新しい都市型工業の立地条件に適しているということをＰＲいたしまして、区内事業所の減少の歯止めということで展開する事業でございます。具体的には、西大井駅前南地区の再開発事業の保留床を取得し、ベンチャー企業の集積拠点を整備する、このような内容になってございます。\n４６ページ以降はその他ということで、最後のまとめをしてございます。４７ページ、４８ページは産業振興事業助成補助金、区商連工場協会連合会など、産業関係団体への事業助成金を交付しております。\n最後になりますが、５１ページ、ＩＴ基礎技能講習事業でございますが、中小企業のパソコン教習室を利用いたしまして、国の助成事業でございますＩＴ基礎技能講習事業の一環として初級パソコン講座を年間７０回実施する予定でございます。\n説明は、以上でございます。"},{"i":52,"speaker":"冨田戸籍住民課長","text":"続きまして、戸籍住民課の事業概要をご説明申し上げます。\n１ページに、係、分掌事務がございます。今年から組織改正になりまして、戸籍届出係に、従前、庶務機能、庶務係があったものを、こちらのほうに吸収してございます。それから、一番下のところ、住基ネットワーク担当、これは今年度４月に新設をいたしました。後ほどご説明いたしますが、住基ネットの開発のための組織でございます。職員総数６８名で実施しております。\n２ページでございます。住居表示管理事務、住居の表示管理、住居の表示を合理的な分かりやすいものにしようということで、昭和３８年に品川区では条例をつくりまして、昭和３９年以降４２年までに住居表示を全部変えております。他区にはまだ全部終わっていないところもあるようでございます。住居表示としましては、新築の建物をつくった場合には住居番号をつけるということで、その事務を行っているところでございます。\n街区の案内板ということで、現在総数７７基ございます。そのうちの街角、あるいは駅前で特に充実したような形の案内表示板、公共サインの整備ということで、事業を実施しているところでございます。\n３ページは戸籍事務でございます。地方自治法が改正になりまして、国からの法定受託事務ということで実施をしております。人の出生から死亡までの身分関係を公証するものということで、戸籍の原本等、台帳の整備をしているところでございます。\n一番下のほう、総数ということで、３カ年の取扱件数がございます。２万件強ということで、総数としては、処理の件数はあまり変わっておりません。\n４ページをお願いいたします。下のほう(4)戸籍証明手数料ということがございます。従前は品川区の条例によるものと、それから戸籍手数料条例、政令によるものと２種類ございました。このたびの改正によりまして、戸籍手数料令が廃止になりまして、全部品川区の手数料条例に基づくものに変わってございます。5,５００万円、額としては大体例年同様でございます。\n５ページの中ほど、成年後見制度概要ということで記載してございます。従前、禁治産、準禁治産というような制度がございました。当該人、あるいは関係の方にあまり好ましくないということで、名前を「後見」、あるいは「保佐」等に改めたものでございます。\nまた、登記制度ということで、従来は戸籍に「禁治産」「準禁治産」等の記載をすることがございましたけれども、今後はその記載を改めまして、登記所に対しての登記制度が創設されたものでございます。\n６ページは人口動態調査でございます。統計等によりまして、出生、死亡、死産、婚姻及び離婚に関しては保健所を経由して厚生省のほうにその数値の動きを届け、提出をしているところでございます。\n右側のほうに合計特殊出生率がございます。数値が2.０９を切ると人口が減少傾向だというふうに言われておりますけれども、品川区のほうは0.８８、全国的に見ても1.３４ということで、全体として減少傾向が示されている状況にございます。\n誕生記念品でございます。出生に当たりまして、品川区内に住所を有している方が出生した場合には、記念品ということでフォトスタンドを交付しているものでございます。\n次に、７ページはを住民基本台帳事務でございます。戸籍に関しては身分関係を公証する制度ということでございます。住民基本台帳に関しましては居住関係を公証するものということでございます。\nここに書かれております、戸籍の附票と申しますのは、住民基本台帳法に基づいてつくることが義務付けられているものでございますが、戸籍と住居、戸籍と住民基本台帳を相互に関連付けるものということで、戸籍の附票の制度がございます。\n次に８ページでございます。異動処理の件数、転入、転出の事項がございます。転入が１万9,０００件、転出１万7,０００件、転入のほうは、この３カ年を見ますと、ほぼ横ばいの状況でございます。転出のほうは１万8,０００から１万7,０００ということで、３カ年の傾向を見る限りにおいては、若干転出が減少している。これだけ見れば、差し引きで品川区の人口が若干増えるということが一応言えるかなというふうに思います。\n９ページをお願いいたします。印鑑登録の事務ということで、これも中ほどから下のほうに、登録者の総数がございますけれども、１８万余で、同様の規模でございます。\n印鑑登録につきましては５０円、証明に関しては３００円の手数料ということになります。\n１０ページ、大井町サービスコーナーでございます。時間外にも取り扱ってほしいというご要望に応えまして、平成５年からやっているものでございます。８時から１７時まで、ただし、証明書の写しの交付が主体でございまして、この間、８時から８時４５分の間、あるいは５時から７時までの間につきましては、その場では機械が止まっておりますので、写しの交付はできませんので、午後あるいは翌日に改めておいでいただいて交付をするというような扱いとなっております。\n一番下のほうに総合計がございます。平成１２年度２万4,１７１件、平成１０年度が２万３７８件ということで、この傾向を見ますと、若干ずつ増加の傾向が見られるというふうに思います。\n１１ページは外国人登録事務ということでございます。外国人の居住関係およびこちらのほうは身分関係もあわせて把握し、公正な管理に資するということでございます。\n主要国別登録人数ということで、合計の欄がございます。平成１２年度は8,９８９名ということで、過去の経緯を見ますと、若干ずつ増加の傾向にあるというふうに言えると思います。\n１３ページは住民基本台帳ネットワーク開発ということで、新たに組織を設けまして、今開発中のものでございます。平成１１年に住民基本台帳法が改正になりまして、一部の情報については集約をして、それを一元管理して、必要な処理を行うということで、現在システムを構築中でございます。\n内容のところでございますが、(1)本人確認情報（四情報等＋住民票コード）、四情報と申しますのは、氏名、住所、性別、生年月日。住民票コードと申しますのは、都道府県のほうからコード番号の指定がございまして、これを合わせて指定の機関へ情報を送る。その送られたところでは、国等の行政活動にそれを活用するということでございます。それが１番でございます。\n２番目のほうは、これが全部全国的につながりますので、住民票の写しが一部広域交付が可能になる。これにつきましては、平成１５年８月から交付、全国どこでも住民票が取れるというような形で、現在開発中でございます。\n転出、転入の窓口の手続きが１回で済む。これも同じ平成１５年８月からです。\nそれから、住民基本台帳カードの交付、これも平成１５年８月からということでございます。\n平成１４年８月には、システムとしてはある程度の内容が固まりまして、情報処理機関のほうに提供いたします。その後ですけれども、国の段階等でその情報を活用して、国等の事務に若干使われることになる。住民票の写しの交付自体は平成１５年８月からということで、２段階ということになっております。\n下の図は、それを図示したものでございます。一番下の品川区から東京都ネットワークというところで通信回線を使いまして情報を送ります。送る情報としては、基本的には四情報＋住民票コードということでございます。\n東京都のほうは全国ネットワークというところに情報が送られます。この全国ネットワーク、処理するところが指定情報処理機関ということでございますけれども、現在財団法人、地方自治情報センターというところが指定情報処理機関となっております。ここで全国的な情報を集約いたしまして、国の行政機関等が活用するというものでございます。\n併せて、品川区、あるいは各市町村単位でございますけれども、住民票の写しが全国どこでも取れるようになる。それが大体のネットワークの概要でございます。\n以上で、終わります。"},{"i":53,"speaker":"松崎税務課長","text":"それでは、税務課概要について、ご説明申し上げます。\n今回の組織改正で、課税課と納税課が１本になりまして、税務課ということでスタートした課でございます。\n管理部門、特に税務係の部門を一元化することによって、適正な賦課、確実な徴収、これを目標に税収の確保を図っていく部門でございます。１０係で構成されております。\n２ページの納税推進担当以下につきましては、徴収推進担当課長が主として主管する部分でございます。\n３ページをおめくりいただきたいと思います。区が使っている税金の主なものは住民税と軽自動車税、たばこ税、この３本でございます。財政に占める割合が２５％ほどでございます。そのうち特別区民税が２２％ほど、軽自動車税は0.１％、たばこ税は2.５％ぐらいの割合を占めているものでございます。\n税収の傾向といたしましては、普通徴収が伸び傾向にある。特別徴収はほぼ一定した状況にあるというふうに言えるかと思います。\n普通徴収と特別徴収の比率が、現在、普通徴収１に対して特別徴収２、１対２、税収構造としては対安定した構造、特別徴収が９９％以上、約１００％近く取れますので、安定した構造で税収を上げられるという、区によっては１対１で、税収率が違いますので、普通徴収が高いと、どうしても税収率が低くなるという傾向がございます。これが一般的な傾向でございます。\n軽自動車税につきましては、５０ＣＣのバイクから軽自動車までを扱っているという制度でございます。\n５ページはたばこ税ですが、傾向といたしましては、売上本数がどんどん減っておりますので、税収としては下がって、３０億円前後、ただ、税収の税目としましては１００％、これは取り漏れがないという税目でございますので、区にとっては非常にありがたい税目であるということは間違いないというふうに言えると思います。賛否両論いろいろあるところでございますので、これ以上のコメントは差し控えさせていただきます。\n４につきましては、仮免の部分でございます。\n次に７ページ、一番問題の、委員の皆様のお手元には一番ホットな徴収率をお示ししてございます。ここにあるのは４月末現在ですが、お手元に席上配付させていただきましたのは、５月末現在で出した、今日の午前中にほぼ確定したものでございます。これでいきますと、特別区民税のところで９0.２６％、７年ぶりに９０％を超えました。今回２３区で９０％を超えたのは品川区と文京区の２区だけではないかというふうに思います。９０％が目標でしたが、達成することができたということでございます。全体で見ましても９1.０６％、昨年と比較しましても0.４％大きく伸ばすことができたというふうに言えるかと思います。\n特に私ども税務課の特徴といたしましては、総予算が１億5,０００万円ぐらいです。ただし、税収の中で占める割合は約４００億円近くを納めていただいておりますので、一番効率のいい財政を執行しているのではないかというふうに自負しているところでございます。\n以上でございます。"},{"i":54,"speaker":"太田保険年金課長","text":"それでは、保険年金課の１ページをお開きいただきたいと思います。保険年金課でございますが、今年の４月組織改正によりまして、旧国民健康保険課と旧国民年金課が統合いたしまして、保険年金課というふうに改正をされたところでございます。\n大きく分けまして事業としては３つの事業がございます。一つは国民健康保険事業、二つ目は介護保険事業でございます。介護保険につきましては、介護保険料の賦課徴収の関係を所管をするということになってございます。介護保険の制度の根幹に係わるもの、あるいは要介護認定、保険給付等の部分については高齢福祉課のほうで所管をするという、こういう切りわけになってございます。３点目が国民年金事業ということになってございます。\n組織でございますけれども、７係１主査という構成になってございます。\nそのほかに、後ほど国民年金事業につきましては、制度担当課長のほうからご説明を申し上げますけれども、主として国民年金の事業につきましては制度担当課長のほうが担当するということになっております。\nそれでは、具体的に３ページ以降の説明に入らせていただきたいと思います。国民健康保険事業でございます。１点目でございますが、被保険者でございますけれども、品川区に住所を有する方ということで、本人の意思にかかわらず、健康保険組合などの保険の被保険者、利用者、あるいは生活保護を受けている方等を除外をされて、それ以外の方が、ご本人の意思にかかわらず加入をするという仕組みになってございます。\n加入率は、そこの表にございますように、ここ数年来増加をしているという状況でございます。\n４ページは保険給付になります。医療保険のことでございますので、被保険者がけがをしたり病気になった場合に、保険者である区が保険給付を行うということでございます。\nその部分で、４ページから７ページに記載をしてございますが、主だったものとしては、４ページのア、療養の給付でございます。これは通常の３割負担、あるいは２割負担という部分でございます。医療機関を通じて被保険者に診察、薬剤の支給等を通じて、現物給付を行うということでございます。その際、自己負担、医療費の３割、薬剤一部負担を医療機関に支払っている。残りの７割を区の保険者として医療機関に直接支払う。これが通常の療養の給付という仕組みになってございます。\n５ページは高額療養費でございます。医療費が一定の基準額を超えて自己負担をした場合に、その超えた部分をご本人に還付をするという制度でございます。これにつきましては、本年１月から制度改正がございまして、従来は一般世帯と住民税非課税世帯という２区分だったわけでございますが、制度改正によりまして、上位所得世帯という概念が導入をされたということでございます。基礎控除後の所得が６７０万円を超える世帯ということでございます。給与ベースで計算しますと、９００万円弱という数字になろうかと思います。そういうふうな形で制度改正をされているということでございます。\n６ページは、その他の給付ということで、出産育児一時金、葬祭費の支給ということで実施をしてございます。\n医療費の自己負担でございますが、医療費については３割を一部負担ということでございます。\n退職者医療の適用を受ける方については、本人２割、被扶養者、入院２割、通院３割ということになっているということでございます。\n老人医療については、そこにございますように、医療費の１割を負担することを原則とするということになってございます。\n７ページの参考のところで、退職者医療制度、老人医療等の説明を掲載をさせていただいてございます。\nその他、一部負担金の減免、徴収猶予、不正利得、不当利得、第三者行為等の事業内容を実施しているところでございます。\n８ページは保険料でございます。保険料につきましては、医療給付分と、介護納付金、介護保険制度が導入をされましたので、第２号の被保険者、４０歳から６５歳未満の方については、国民健康保険に加入している場合、従来の医療給付分に介護納付金を上乗せをして、一体として徴収をするという中身になってございます。\n賦課限度額は、そこに記載をしているとおりでございます。\n医療給付分の所得割は、平成１３年度は１００分の１９４ということでございます。均等割につきましては２万7,３００円ということでございます。\n介護納付金につきましては、所得割が１００分の２０、均等割が8,１００円ということになってございます。\n９ページは、収納状況ということで、これが時期がちょっと間に合いませんでしたので、平成１２年度は４月末現在で掲載をさせていただいております。現年分で８6.１６％、滞納繰越分で２7.０３％ということでございます。\n最終的な数字、まだ微調整がございますけれども、５月末につきましては、現年医療が８7.６％から８7.７％ぐらい、ちょっと微調整がございますので、８7.６％から８7.７％ぐらいということでご理解をいただければと思います。\n１０ページは国民健康保険運営協議会でございます。国民健康保険事業の適正な運営を図るということで、区長の諮問機関、これは国民健康保険法に設置が義務付けられております。国民健康保険運営協議会を設けて、重要事項について審議をするということで、審議事項については、アからエに記載をしているとおりでございます。\nまた、委員構成も、(2)のアからエに記載をしているとおりでございます。\n保健施設の関係で、被保険者の健康の保持増進を図るということで、(1)から(4)の事業を実施しておるところでございます。\n１２ページで、広報活動で、啓発ということを含めて、そこに記載の広報活動を実施しているというところでございます。\n１３ページの介護保険事業のほうをご説明をさせていただきたいと思います。被保険者でございますけれども、ご案内のとおり、４０歳以上の区民が被保険者になるということでございます。第１号被保険者は６５歳以上の方ということで、全員になるということでございます。第２号被保険者は４０歳以上６５歳未満で、医療保険に加入されている方ということでございます。４月１日現在の加入状況については、そこの表に記載をしてあるとおりでございます。\n１４ページは介護保険の保険料でございます。第１号被保険者の保険料は５段階に区分をされているというところでございます。それぞれの保険料については、第３段階を基準として、それぞれそこに掲載をしているとおりになってございます。\n軽減措置ということで、国の特別対策によりまして、昨年の１０月から本年９月までは、記載してございます保険料の半額ということになってございます。今年の１０月以降が、そこの表に記載をしている保険料になるということでございます。\n区の独自対策により、先の第１回定例会において条例改正をして、平成１３年１０月以降、第１号被保険者の所得階層が第２段階で一定要件に該当する方を対象として保険料を第１段階の保険料に減額をするという制度改正を実施させていただいたところでございます。\n詳細につきましては、高齢福祉課とも協議をしながら準備を進めているところでございます。今日は、こういう制度改正をしたということだけご案内をさせていただきたいと思います。\nそれから、第１号被保険者の収納状況、これも４月末現在でございますが、そこに記載をしているとおりでございます。\n最後に、第２号の被保険者の保険料でございますが、国保加入者については、先ほどご説明をしたとおりでございます。国保以外の健康保険加入者については、各組合等で決めているという状況でございます。\n介護保険の給付等については高齢福祉課で所管をするということになってございます。\n国民年金事業については、担当課長のほうからご説明をさせていただきたいと思います。"},{"i":55,"speaker":"小野年金制度担当課長","text":"それでは、国民年金事業についてご説明をさせていただきます。\n国民年金制度は、老後の所得保障を目的といたしました社会保障制度でございまして、加入者が保険料を払い、それに応じて年金給付を受けるという拠出制の社会保険方式をとっております。\n昭和３６年に自営業者のための制度として発足をいたしましたけれども、昭和６０年に法改正がございまして、満２０歳以上６０歳未満の人はすべてが加入することが義務付けをされております。いわゆる国民皆年金制度に改められまして、国民年金については全国共通の基礎年金という形になりました。\n厚生年金あるいは共済年金につきましては、下の年金制度の体系の図表にありますように、基礎年金の上乗せとして報酬に比例した年金を支給する制度に再編をされております。国民年金につきましては、保険者が国ということでございますので、年金の業務は主に社会保険庁と出先機関の社会保険事務所で行っております。区市町村につきましては、受託事務ということで実施をしているところでございます。\n１６ページにまいりまして、平成１１年度に年金制度の大きな制度改正がございまして、将来の現役世代の負担を軽減するという考え方によって、負担と給付の見直しをしております。ただ、保険料と基礎年金の額につきましては、諸事情を考慮いたしまして、特例措置として据え置かれているという現状でございます。\n給付につきましては、主に厚生年金の給付が５％の適正化を図る、あるいは比例報酬分の部分が支給年齢を繰り上げるというような形で改正をされております。\nその他、学生についての卒業後に納付ができる納付特例制度が平成１２年度から導入をされ、あるいは国民年金保険料の半額免除制度、これが平成１４年から実施をされるという形になっております。\n１７ページをお開きいただきたいと思います。年金の資格事務でございますけれども、区がやっている内容といたしましては、諸届の受付、国民年金の名簿の管理でございます。ただ、これにつきましても、諸届の受付は、後ほど説明をいたしますけれども、第３号被保険者についての届出は平成１４年度から事業所等から直接社会保険事務所への届出になります。また、名簿管理については廃止をされるという形になっております。\n被保険者でございますけれども、先ほどご説明をいたしましたように、２０歳から６０歳未満の方について、年金制度に加入するということで、国民年金の第１号被保険者として、自営業者その他の家族、学生、無職の人が、いわゆる国民年金の固有の被保険者という形で第１号被保険者となっております。その他、会社員、公務員については第２号被保険者。第２号被保険者の配偶者については第３号被保険者という形で、すべての国民の方が強制加入をいたしてまいります。\nまた、２０歳から６０歳の強制加入の対象でない方につきましても、年金額の満額を確保するため、あるいは資格を得るため等任意加入の制度が設けられているところでございます。\n１８ページにつきましては、被保険者数の推移がございますけれども、品川区におきましては徐々に減少しているという傾向が表れております。ただ、全国的に見ますと、厚生年金から国民年金へ移っていくという移動、あるいは第１号被保険者について強制的に加入をさせているという状況もございまして、加入者は増加をしているという状況が出ております。\n続きまして、１９ページの保険料でございます。保険料につきましては、主に認証の現認事務が中心になっておりまして、予算の大半が印紙の購入費という形で組まれております。内容につきましては、保険料の収納免除、免除申請の受付、還付申請の受付等でございますけれども、これも平成１４年４月には収納事務および還付事務につきましては国のほうへ移管をするという形になっております。\n納付の対象者につきましては、第１号被保険者および任意加入者については、国民年金の保険料の納付の期限がございます。第２号被保険者、第３号被保険者につきましては、それぞれ被保険、雇われているほうの年金からの拠出金という形で賄われているところでございます。\n納付につきましては、追加の保険料の納付等、１０年までさかのぼってできるという形の制度がございます。\n２０ページにまいりまして、割引のあります保険料の前納制度がございます。内容につきましては、表に書かれているとおりでございます。\nまた、保険料の免除・学生納付特例についてでございまして、こちらのほうも表に書かれている要件の中で免除あるいは納付の特例が認められるという形になっているところでございます。\n２１ページは保険料の納付の推移等が出ております。全般的な傾向といたしまして、景気の低迷、あるいは年金不信等によりまして、納付離れが進んでいるというふうな状況が出ております。検認率が低下をし、免除率が増加をしているという傾向が出ております。\n給付事務につきましては、年金の裁定請求、一時金の請求、受付、審査ということを実施をしているところでございます。\n給付の種類につきましては、２２ページの表にございますように、老後の生活保障として、中心になります老齢基礎年金、それから、障害者の生活保障としての障害基礎年金、そして、遺族のための子どもの養育の保障という性格がございます遺族基礎年金、そして、妻自身の年金が受け取れるまでの期間の老後の保障という形になってございます、寡婦年金。そして、国民年金制度が始まったときに既に制度漏れになっている方の救済制度としての老齢福祉年金等がございます。それについては表に書いてあるとおりでございます。\n２４ページにつきましては、繰り上げ、繰り下げの支給率等、あるいは一時金等が表として出ておりますので、ご覧をいただければと思います。\n２５ページは、支給の金額が出ております。現在、老齢基礎年金の年金額が８０万4,２００円、月額にしますと６万7,０１６円ということになります。これにつきましては、先ほど申し上げましたとおり、年金の額については現在据え置かれているという状況になっております。\nその他、脱退一時金、あるいは年金の制度の流れ等については、２６ページに記載がされている状況でございます。\n２７ページに、年金の受給権者がございますけれども、受給権者につきましては、旧制度、いわゆる昭和６１年に改正前の制度によるものが減少し、新制度に受給権者が増えている傾向があるということでございます。\n２８ページに出ております国民年金基金につきましては、自営業者の第１号被保険者についての上積みの年金を支給する制度としてできているものでございます。\n２９ページ、趣旨普及につきましては、広報あるいは社会保険庁の事務所等と連携をした街頭相談等を実施しているところでございます。\n以上でございます。"},{"i":56,"speaker":"南委員長","text":"長時間にわたって、それぞれ一挙に説明をしていただきました。以上で、区民生活事業部の説明が終わりました。\nこれより質疑を行います。それでは、質疑がございましたら、どうぞ、ご発言をお願いいたします。"},{"i":57,"speaker":"藤原委員","text":"産業振興課の７ページの勤労者生活資金融資あっ旋についてお伺いしますが、融資実績が平成１２年度で３件しかありませんし、融資率が１3.９６％しかないですよね。まず、この実績の３件という少なさについて、何か理由があれば教えていただきたいと思います。"},{"i":58,"speaker":"市川産業振興課長","text":"８ページの表を見ていただいて、平成１０年度と１１年度、１２年度、この数字の開きが顕著になってございます。平成１０年度までは、平成１０年度に示してございます実績と同じような推移でまいりまして、平成１１年度、１２年度と急激に数字が落ちました。一つ、考えられることは、数字で出しておりませんが、実際に申し込みに対してどうだったのかということで申し上げますと、平成１０年度は４３件の申し込みがあって、２０件の実行、同じように平成１１年度は２１件の申し込みに対して２件、平成１２年度は２７件に対して３件、こういう数字の推移になってございます。\nまず、申し込みの数自体がかなり減っている。さらに、実行件数が減っているということでございますけれども、実行件数が減っている理由は、信用保証機関で否決をされたものがすべてです。要は、信用保証機関の側から、返済に不安があるということで、信用保証をつけられないという回答がきての否決です。\n具体的な理由といたしましては、ほとんどの方が多重債務を負ってございます。それで、平成１１年度、平成１２年度の傾向を、特に平成１１年度に応募件数が減ったことから、ＰＲ不足ということがあろうかと思いまして、かなり広報等を通じましてＰＲをいたしました。ＰＲをいたしますと一定の数の申し込みはございます。ただ、実際に申し込みがあっても、ほとんどのお客様について信用保証が付けられない結果になる。\n信用保証の成否はともかくとしても、申込数が減ったという背景には、一つは、金融機関、例えば都市銀行を初め、信用金庫、信用組合、一般の金融機関で小口の資金貸付を手軽に行っているケースがかなり増えてきた。また、カードローンとか、そういった庶民金融の利用も一方である。こういった小口資金に対する金融事情が変わってきたということがございまして、この制度本来、福利厚生が行き届かない中小企業の従業員に対して一定の小口の金融をあっ旋するというこの制度本来の趣旨のベースになる事情が大分変わってきているのではないかなということで認識をしてございます。したがって、今年度の推移を見て、この事業自体の存否について検討をしてまいりたいということで考えてございます。"},{"i":59,"speaker":"藤原委員","text":"まさに、今課長にご発言いただいたとおり、事務事業内容に載っている、事業としてあまりにも件数が少ないですし、平成１２年度で応募が２７件で、３件しか通らない。保証協会等がだめだという理由が、多重債務者というのが１番で、今のお答えの中で、個々の方たちがカードローンで借りちゃうというご返事がありましたけれども、カードローンとかをどんどん借りていっちゃうと、逆にまた多重債務者になっちゃうわけですよね。だから、保証協会が保証するということで、区としてはというお考えはあると思うんですけれども、もうちょっと甘くという言い方をすると言葉は合っていないかもしれませんけれども、カードローンとか、サラ金とかに行かないで、歯止めがかかるようにという形にならないものかということと、あと、ＰＲ不足ということで、広報等に出したときに件数は上がりましたがというお答えでしたが、上がって、平成１１年度で２１件、平成１２年度で２２件しかこなかったんでしょうか。"},{"i":60,"speaker":"市川産業振興課長","text":"先ほど一部説明に適切さを欠いたかもしれないんですが、決してカードローンの利用を私どもは積極的にすすめているとか、そういうことではございませんで、一般的な制度として金融機関の一般的な小口資金の金融、それからもう一方で、いわゆるカードローン等の手軽に借り入れることができてしまうようなものがある中で、総体的に申し込みの数が減っているという状況認識ということで申し上げたつもりです。\n今委員ご指摘のように、私どもはこの事業のＰＲの一番の目的は、ほかの同じ借りられる能力のある方は、他のカードローン等の手段によるよりは、こういった身近な制度がありますということをＰＲすることが趣旨だと思ってございます。\nただ、かなりの手段を尽くしてＰＲをしてきても、この３、４年前の状況と比べると、絶対的な件数が落ちているという事実がございます。先ほど申し上げましたけれども、一方で、中小企業、特に小規模企業の事業者に対する一つの支援策という位置付けと、事業の現実の数字、それと、あと、代替手段と申しましょうか、同様の制度が東京都の制度としてございますので、そういったことを考え合わせて検討をしてまいりたいと思っております。"},{"i":61,"speaker":"藤原委員","text":"もう１点だけお伺いしますが、特別区税の件でご質問したいんですけれども、特別徴収１００％にならない。というのは、会社が従業員の方からお預かりしているわけですよね。実は法人の消費税が会社にきたとき、中を見ますと、消費税は国の代わりに預かっていただいている税金ですという文面が出てくるんです。事業主のところのグラフで。まさにそれと同じで、特別徴収というのは、従業員の方から会社が一時的にお預かりしているお金であって、会社の運用資金ではないわけですので、課長は先ほど、「全部で９０％以上いったのは品川区と文京区でした」という、すばらしいご説明があったんですが、特別徴収が１００％いかないのはちょっと疑問なので、そこだけ教えていただきたいと思います。"},{"i":62,"speaker":"松崎税務課長","text":"税務課の３ページのところをお開けいただきたいと思います。まず、具体的な例で申し上げたほうが分かりいいと思います。私ども品川区から給与をもらって，税金を引かれるわけですが、そのとき納税義務者ということで、我々は特別徴収義務者である区長が私どもの税金をプールするわけです。翌月の１０日までにプールしたものを品川区に納めるというシステムになってございます。本来ですと、それがうまく回転していれば１００％になる。それがならないという理由は大きく２つぐらい挙げられると思います。\nまず、１点、預かり金として預かっているものを持ったまま倒産する場合、もう払えない状態になってしまう。企業そのものが倒産してしまう場合、それが１点。２点目としては、預かり金を運転資金に回してしまう場合、資金繰りがつかない場合は、従業員から預かっている税金相当分を運転資金に企業が回してしまう。大きく分けると、この２つがあるかと思います。\nそのほか細かいものはいろいろあると思いますが、これが１００％にならない一番大きな理由だというふうに考えております。"},{"i":63,"speaker":"藤原委員","text":"それは、しようがないということでしょうか。"},{"i":64,"speaker":"松崎税務課長","text":"税務課のサイドからすれば、１００％いただかざるを得ないので、しようがないという言い方はできませんというふうには理解してございますが、預かり金としてお持ちになっている部分を経営者の才覚によってどのように運転するか、税金というのは、基本的には滞納を別とすれば、１年のスパンがありますから、延滞金を覚悟で運転資金に回すということまでも我々はとやかくは言えない。１年かけて全部滞納のないようにお支払いいただければ、私どもにとって一番ベターであるというふうには理解しております。"},{"i":65,"speaker":"本田委員","text":"二つお尋ねします。一つは、広域斎場の件ですけれども、一部事務組合にお仕事は委ねてあるわけですけれども、斎場用地が２万2,５００m2ですか、この用地が都有地で、無償で使えるのか、使えないのかというのが、以後の利用上にも大きく影響してきますので、これが有償だという話も聞いてはいるんですけれども、現時点でどうなっているのかというのが１点。\nもう一つが大変問題なんですけれども、私も軽自動車を持っておりまして、年１回、営業ナンバーの軽自動車ですから、3,０００円を払うんですが、今のご報告で、徴収するのが４万件、５０ＣＣのバイク1,０００円からいろいろあるわけですけれども、毎年徴収しているわけですが、これを徴収単価というのがあるんだろうし、１億の何某の経費で、先ほど何十億円と言いましたが、品川区の中で一番仕事をしているというような意味の発言がありましたけれども、自分で払っていて、軽自動車は今車検がありますから、車検のときに一括して払えば大分軽減されるのではないかな。何も毎年徴収をやらなくても。これは品川区単独では税法上できないんだろうと思いますけれども、それは検討の材料になっていないのかどうか。５０ＣＣバイクの1,０００円徴収にかなりのコストがかかっているというお話も伺っておりますが、何らかの改善策がそこにはあるのではないかと私は思うんですけれども、今のご報告を聞いていますと、４万件を超えておりまして、これは全国的な問題でしょうけれども、どう思っておりますかというのが１点。\nもう一つは、予算特別委員会のときに区長がご答弁されていたように記憶しているんですが、今は分権が進んでいるわけですが、地方自治体の自主財源をどう確保していくかというのは、どこの自治体も頭の痛い、また大きな問題でありますけれども、遠くにおいては、財政課のほうで研究会をつくって、それを対処しているというようなところがあったように記憶しているんですが、そういうことが財政サイドでどういうスタッフで、どんな検討がなされているのか。もしあればお聞かせいただきたいと思います。"},{"i":66,"speaker":"宮地区民課長","text":"広域斎場、特に用地の問題ですけれども、都有地を無償で使用できるのかということでは、最初の姿勢は無償ということで進めてきてございました。昨年の１２月の段階で、もう一度用地のことで、今年度の予算編成もございますので、確認をしたところ、なかなか厳しいということで、無償か、せめて７割減額かということで、ぜひ前向きの答えをいただきたいというところで港湾局の方たちも立ち会っていただいた上での打ち合わせ会があったと聞いております。\nその後、全然回答がございませんで、その間、大田区議会の理事長さん等を初めとして、それぞれの議員さん方、あるいは都議会議員の議員さん方が間に入って、いろいろとお話を重ねてきたところでございますが、答えがない中で、今度６月７日に、１名の区長は出席できないんですけれども、４区の区長と、私どもの職員が一緒に副知事のところに参りまして、副知事、港湾局長同席の上で、その件について回答をいただくことになっております。この間ずっと、その下打ち合わせをしてきている中では、７割減額もかなり厳しい状況だということで、あきらめないで、きちんとそういう形を訴えていこうということで、７日はそういう姿勢で行くということで、それで最終的に回答をいただくということになっているのが、現状の段階でございます。"},{"i":67,"speaker":"松崎税務課長","text":"先ほど大見えを切ったばかりでございますが、税収に当たりまして、軽自動車税が実はアキレス腱でございまして、正確に徴税コストを計算したことはないんですが、特に５０ＣＣのバイクの1,０００円をいただくために、区によって違うんですが、人件費等を入れますと、1,５００円から1,８００円ほどかかるというふうに言われています。これが滞納で、８０円の通知を１０回出しますと８００円足されますから、かなりのコストがかかってしまう。既に賦課をする段階で1,０００円以上を超えているというのが現状だというふうに聞いております。\nしたがいまして、これをどういうふうに打開するかということで、三税、いわゆる都も含めまして、国税も含めまして、いろいろ協議をしているのですが、追い追いと軽自動車税と、都税で扱っている普通自動車税を一本化する。最終的には一本化という方向も検討されているようです。\n区長会等を通じましては、軽自動車税の取り扱いについて何とかしてほしいという申し出は毎年のようにしているようでございます。\nただ、地方と２３区では軽自動車税の税収の占める割合が全く違って、都会ですと非常にお荷物なんですが、地方ですと、一家に何台も５０ＣＣのバイクがあるとか、軽自動車が何台もあるということで、大変大きな税収になっているようで、足並みがそろわないというのが現状のようです。ただ、私どももこれは大変な徴税コストがかかる。ある意味では9,０００万円の税収を上げるために、これ以上かかっているのではないかという認識そのものは持っております。例えばナンバープレート１枚にしましても、バイクので２００円で、車ですと2,０００円ですから、3,０００円いただいても、新車の場合は2,０００円は飛んでいってしまうということになるので、今後これは市長会のほうに入るということですので、ここを通じまして抜本的な税制の改正をする必要があるというふうに考えております。\n２点目の財政ですが、財政サイドでどういうプロジェクトがあるか詳しくは存じませんが、税務サイドでは、新税検討会というのを持っております。その中でいろいろ新税について検討をしておりますが，再々区長が答弁してございますように、新税については現在のところ検討をしていないというか、新しい税目をもって区民の皆様に新しい負担をお願いするということは考えていないという。今回、徴収率を多少上げておりますが、今のところ収入率を上げることで、新しい税目を設定する以上の税収を上げる可能性があるという認識には立っております。"},{"i":68,"speaker":"本田委員","text":"事業概要の説明ですから、詳しくはお聞きしませんが、先ほどの用地問題については、確かに５区の一部事務組合をつくっての報道にはなっておりますけれども、本来２３区全体の問題だと私は思っているんです。だから、都内の公営斎場は瑞江だけで、本来公営斎場については、区市の事業であるから、都が土地を出せないというのは私はおかしいと思っているんです。ですから、当初の方針どおり無償提供するように、７日ということですから、どういう回答が出るのか期待をして、見守っておきたいと思います。ご努力をいただきたいと思います。\n税務の問題については、軽自動車の問題は件数を見てみましても、大分問題があるなと、自分で納めていながら感ずるわけです。ぜひその辺、声を上げるところは上げて、それぞれのところで改善を図っていただきたいと思います。"},{"i":69,"speaker":"原委員","text":"事務事業概要ですから、確認を二、三させていただきたいと思います。一つは、区民生活事業部は四つの業務を統括していて、大変幅広くて、区民に密着していくうえで、その努力は大変なんじゃないかなと思うんですけれども、最初のところで、保養所の公営化の説明があったんですけれども、これは我々行革の中でもそれぞれ見直しということの中で、申し込み方法をもう少し簡略したらというよう提案をさせていただいて、こういう形になったわけですが、今年から始められて、現状ですね、例えば申し込みに混乱があったとか、あるいは料理に差がついたとかというようなことがあるようだったら、ちょっと確認をさせていただきたいと思います。\nもう一つは、なぎさ会館の利用率ですけれども、平成１０年を境にして落ちてきている。これは各町会会館を葬祭できるような形にされたということも含めて、そこから波及されているのかどうか、あるいはほかの理由があるのか。\nもう１点は、地域活動課のほうになるんですかね、各事業が各町会の予算を付けて、利用が増えてきて、それを町会に落として、その町会に付けてもらうという、かなりのボリュームを町会がこなしているという意味では、この中でも、町会の方たちに聞くと、「大変なんだよ。資料だけでもこれだけの量が付くんです」ということをよく言われるんです。その辺のところをもう少しいろいろな意味で簡略化する、あるいは負担割合を整理をして、町会のほうの協力をうまくしていただくような形を考えていらっしゃるのか。そこら辺をお願いいたします。"},{"i":70,"speaker":"宮地区民課長","text":"保養所関係ですけれども、今、直近で５月末に締めたところのがあるんですが、平成１２年度とそれぞれ比較しますと、例えば箱根荘ですと、昨年1,２９１名の利用、今年度1,６７１名の利用で、３８０人多くなっております。暖景苑で、昨年1,０８５人、今年度1,１０３人で、１８人多くなっています。品川荘が２０人ほど昨年より少ないんですけれども、全般的に見ますと、ご利用される方が非常に申し込みしやすく、現地清算ですので、利用しやすくなったというふうに、今のところ考えておりますが、今後も進行管理表を見ながら、いろいろと様子を把握していきたいと思っております。\nそれから、なぎさ会館ですけれども、いろいろなところでまた便宜が図られるような形になってきまして、必ずしもなぎさ会館だけではないような状況になってきたのかなというのも一つありますが、やはりまだまだ利用のＰＲや、利用のしやすさ等で見直すことができるところもあろうかと思います。今年いろいろと検討できるところを着手しまして、ぜひ利用率を上げていきたいというふうに思っておりますので、もうちょっと様子を見ていただければと思います。"},{"i":71,"speaker":"長田地域活動課長","text":"３点目の町会の負担の問題でございますけれども、最近では町会のほうも会長を初め、役員の方々が高齢になっているというようなことはよく耳にします。そういった意味で、町会の活性化というのは、私どものほうでも重要な課題だというふうに捉えておりまして、昨年の４月１日、地域センターということで見直しをして、地域事務にも目を向けると、こういう形で実施をしてきたところでございます。\n実際の町会は、特に掲示板の関連ですとか、回覧の文書等、これが各課、あるいは関係の団体から非常に多うございます。これだけでも悲鳴を上げているというのも現実の問題だというふうには思ってございます。\n私どもそのほかのメディアを使って周知を図っているわけでございますけれども、町会を通じて回覧板等で周知をするという方法は昔から行われていたやり方で、事業の周知の効果の度合いも高いというようなことの認識の中から、精いっぱい地域センターのほうで、そういった部分のお手伝いはさせていただくわけでございますけれども、この部分につきましては、見直しはもちろんやっていくわけでございますけれども、やはり周知度の問題から言っても、かなり確実に目に触れるというようなことがありますので、継続はしていきたいと考えています。軽減の努力につきましては、今後も引き続き努力してまいりたいというふうに考えてございます。"},{"i":72,"speaker":"原委員","text":"町会のほうも、今お話がありましたけれども、町会が大変なことになっているところがあるんです。だから、地域センターの中での対応、あるいは地区委員の対応等、要するに環境を整えていただきたいと思います。"},{"i":73,"speaker":"金高委員","text":"１７ページの消費者相談の件ですけれども、平成８年度から平成１２年度までそれぞれベスト１０まで入っていますけれども、そのうちのベスト５の中に３点の必ず入っているのは、例えば賃貸アパートの相談件数、クリーニング、サラ金というのがそれぞれ入っておりまして、それがベスト５にすべて入っているわけですね。例えばクリーニングの場合ですと、クリーニングの対応というのは、とられたのか、弁償法とか、そういうのが相談の形としてはあるんですけれども、例えばサラ金問題、あるいは賃貸アパート、これらについて、相談を受けたときに、具体的な道筋までの相談を受けるのか、法的な問題でもって、サラ金とか賃貸アパート、法的な問題は１２年度の場合あります。そういう場合はどの辺までの相談に応じてやるのか。それから、例えば法律問題になったときに、区のほうにも法律相談がありますけれども、そういったところから、そっちのほうに行きなさいというだけで、法律相談に行くと、順番待ちですから、その辺のところをどういう形で仕切りをして、どの程度までご本人たちが納得いくだけの相談まで踏み込んでしているのか。その辺の実態というものをちょっとお聞かせ願えればと思います。"},{"i":74,"speaker":"宮地区民課長","text":"相談につきましては、かなり追跡しまして、最後に相談者の感想といいますか、結果の報告まで求めていますので、行きっぱなしということはないんですけれども、それに要する期間が非常に長くて、数カ月にわたるというのもございます。昨年ので、ちょっと私も全体は見れなくて、かいつまんで見たんですけれども、例えば賃貸アパートの場合ですと、敷金を払っているのに、敷金に見合うお金以上のものを出るときに取られて、さらに追加で取られたなどというのが結構ありまして、畳の打ち替えだとか、壁紙の張り替えとか、いろいろあるんですけれども、そのときには大家さんに相談員から電話をする。相談員立ち会いのもとに、どうしてそうなのかという話をして、納得していただく場合もありますし、大家さんの声のほうが通りまして、追加で払わざるを得なかったというのもございますが、最後はきちんと報告事項として相談者の声も含めて、そこで終わったという形になっております。\nそれから、サラ金などについても、これは近代化センターのほうに問い合わせていただいて、本当に問題の場合は、警察のほうに連絡をしてほしいということで、それも警察に連絡した場合は、警察のほうからも問い合わせが、またこちらのほうに戻ってきまして、結果としてどうなったかというのも出てございます。\nその際に、訴訟中のものもございますので、数カ月から１年かかるのはまだ解決していないのもあるんですけれども、どういう状態になっているかというのは把握できているような状況でございますので、そこら辺は相談員も国民生活センターの研修も受けておりますし、相談員同士の問題、事例研究とか、そういったこともやっておりますので、能力アップということもやりながら、また、相談員が悪くて対応をしてくれないという相談は今のところございませんので、やっぱりきちんと対応していると今の段階では思っております。"},{"i":75,"speaker":"金高委員","text":"もう１点ですけれども、広域斎場の件で、一部事務組合として事業主体の中に、１１ページの議会管理者、事務局という、それぞれ項目があります。事務局のほうで、各組織区より職員体制４名とかが派遣されているというふうになっておりますけれども、例えばこれらの方々の給与問題、あるいは管理者の方々、議会ということで、一部事務組合ですから、例えば議長は大田区、副議長は品川区、あるいは議員として監査云々とありますけれども、これらの方々の報酬というのはあり得るんですか、ないんですか。\nそれから、出向されている場合は、派遣職員ですから出向ですけれども、出向先での給与という形なのか、そういうのも含めて、例えば管理者ですと、無償でやっているのか、あるいはやっていないのか、それとも各区長が就任されていますけれども、報酬といいますか、報償費が支払いされているのかどうか、その辺のことを１点お伺いいたします。"},{"i":76,"speaker":"宮地区民課長","text":"一部事務組合の全体予算が今9,０００万円ほどですけれども、各区の分担金で賄っているんですが、そのうちの建設に係わる部分が4,０００万円ほど、総務といいまして、総務管理費、特に職員の給与関係のほうが5,０００万円ということになっております。その中で、管理者等の費用弁償という項目がございまして、そこまで行く車代といいますか、１回当たり一応は組んではございますが、今のところは全く無償でやってございます。\nというわけで、予算的には管理者等の費用弁償１回8,０００円の４回分の５人ということで、２万９１３円は一応挙げておりますが、今のところゼロでやっております。その他は職員手当等ということで、職員に係わる部分、それから、一般的な一般消費、そういうものを合わせまして、総務管理費でございます。"},{"i":77,"speaker":"金高委員","text":"そうしますと、区より派遣という場合には、職員の方はあくまで一部のほうからの給与負担という形で、いわゆる民間で言えば出向という形と同じですから、その間は管理組合のほうからはそれに見合うだけのものが支給されると。"},{"i":78,"speaker":"宮地区民課長","text":"そのとおりでございます。"},{"i":79,"speaker":"菊地委員","text":"２点だけお伺いをしたいと思います。１点は、事務事業概要の説明で聞いていいのかどうかわからないんですけれども、産業振興の問題でして、マスタープランなんですけれども、私は区民委員会でやらせてもらったのは、今不況の中でどういうふうに区内の中小企業を助けていくのか、この１年間すごく大事な部分になるかと思って、区民委員会に出させていただいたんですけれども、マスタープランの現状の進捗状況といいますか、次回に出していただけるような時期とか、そうしたものを説明を願えればと思います。\nもう１点は、数字だけの問題なんですけれども、国民健康保険７万2,０００世帯余りですか、金額としては出ているんですけれども、世帯数の人数で分かりましたらお知らせ願えればと思います。"},{"i":80,"speaker":"市川産業振興課長","text":"産業振興マスタープランについてのお尋ねでございますけれども、第三次長期基本計画を通して、産業振興に係わる事業計画ということで、３年ないし５年の計画スパンということのプランづくりを昨年来してきてございます。\n具体的には、平成１３年度の予算事業ということでスタートしているものもございますが、計画全体について、現在、受託業者でございます日本総合研究所と最終的な内容の詰め、あるいは表現の詰めをして、これから組織的な意思決定を経た上で、所管の区民委員会に報告をし、公表をしていくという、このような段取りで考えてございます。\nその時期等については、なるべく早期にということで努力をさせていただきます。"},{"i":81,"speaker":"太田保険年金課長","text":"国民健康保険の滞納の世帯、人数ということですが、ちょっと捉え方が、普通徴収であれば１カ月でも遅れれば滞納という状況になりますので、私どもで把握してございますのは世帯数だけでございますけれども、ここのところ１万3,０００件から4,０００世帯ということでございます。"},{"i":82,"speaker":"菊地委員","text":"マスタープランのところですけれども、表現の詰めということですけれども、これは日本総合研究所と区との詰めという意味ですか。〔「はい」と呼ぶ者あり〕\nそれで、内容的には区内の産業、商業、工業の皆さんの意見を聞いて、いろいろつくってこられたんだと思いますけれども、最終的には、そういうところとの詰めなども行ってからということですか。それとも区と日本総合研究所の詰めが終わってから進めていくということですか。"},{"i":83,"speaker":"市川産業振興課長","text":"計画事業のプランニングに当たっては、産業界の関係部署と意見交換などをしてまいりました。そういったことに基づいて、これは行政計画でございますので、特に第三次長期基本計画に基づく事業計画ということで、最終的には私ども区の執行機関として責任を持って策定づくりをするということで、委員がお尋ねの、表現というか、内容について、最終的に産業界と調整をするということは考えてございません。"},{"i":84,"speaker":"菊地委員","text":"実質的に私の望みから言えば、一日も早く議会に出てきて、実際に議論ができればいいなというふうな思いがあるんですけれども、詰めのところで進行性が求められるということであれば、それはそれで仕方がないことなんですけれども、一日も早く中身が出てくるようお願いをしておきたいと思います。"},{"i":85,"speaker":"堺委員","text":"防災課の関係で３点ほどお聞かせいただきたいと思います。\n５番目の、学校等の避難所機能の充実、この件で、連絡会議の開催についてお聞きしたいと思います。この表でいきますと、平成９年度は４１校、平成１０年度は２２校、平成１１年度で３３校、平成１２年度は４０校、学校が５８校ある中で、全部はやっていない状況のようですけれども、その辺のところと、なおかつ訓練の実施に至っては、平成１２年度では１５校しましたけれども、平成９年、平成１０年は３校、平成１１年度は４校、いわゆる学校側の理解、あるいは学校と地域と一緒になった、いわゆる避難所機能にしていくといいますか、状況はどうなのかということですね。\n希望としては、学校がせっかく避難所と明確になっているわけですから、そういう意味からは、訓練についても、あるいは連絡会議についても、区の意向を汲んで、区と学校が対処していただきたいなということですが、その辺のところの状況を教えていただきたいのが１点。\nそれから、１０番目の防災活動広場についても、計画では二十数カ所となっておりますが、現在２０カ所。平成４年度に東大井二丁目を取得して、２０カ所。今は平成１３年ですから、約９年、この間、防災活動広場が新たには取得されていない。土地が出てきていないというのか、あるいはあったけれども、見ていないということなのか、その辺の状況。それが２点。\n３点目は、災害弱者の安全確保の件です。これは平成１１年度のモデル実施で１７町会、平成１２年度が３４町会、平成１２年度は本格的に実施しておるようですが、内容はここにもありますような、災害弱者の支援体制づくりを進めるため災害時の要支援者の把握と名簿化を図ると共に、それぞれ町会・自治会などで支援者の確保に努める。全町会が２００以上あるんでしょうか。そういう中で、この件についても、さっき学校避難所でありませんが、町会の協力を早めにお願いをしたと思うんですが、非常に難しさがあるんだろうとは思いますけれども、この表上で見ると、なかなか思うように進んでいないのかなと思うので、その辺はどうなんでしょうか。状況を含めて、なおかつ、もっと早い時期に、災害弱者の安全確保についての体制がとれるように取り組んでいただければと思うんですけれども、その辺のところを教えていただきたいと思います。"},{"i":86,"speaker":"辻田防災課長","text":"お尋ねの、まず初めに、学校避難所の機能充実ということの避難所の訓練になっている件でございますけれども、平成１１年度までですべての学校で避難所連絡会議が設置されました。ところが、これに至るまでに毎年やっているところ、それから、初めて平成１１年度になって実施したところということで、かなり地域とか、取り組みの場所、日程の差であるとか、そういうものについて非常にばらつきがある。画一とか、均一化して、みんなで取り組めるような意識付けをしていかなければならないというのは、当然私どもの仕事だという具合に考えていますけれども、その辺がなかなか難しいということが１点ございます。\nそれで、連絡会議の開催、平成１２年度は４０校ということで、何しろ取り組みが少ないところについて重点的に実施させていくということで考えて、５８校中４０校という形で昨年はやったわけですけれども、これは学校のほうの取り組みと、地域の取り組みがうまくかみ合わないとうまい具合になっていかない。と申しますのは、本来は学校避難所、施設の管理者というのは学校長でございますけれども、実際に運営していくのは地域の方々ということで、お互いに助け合う、いわゆる助け合いの協力の部分が地域の中で育っていないとなかなかうまくいかない。学校が主体になりますと、学校におんぶをするような形で、何から何までそちらのほうでやってもらうというようなことになってしまいますと、早急に進めたいと思うんですけれども、変な形で進めますと、実際に何か災害があったときにうまく運営できないという形になってしまいます。そこら辺の兼ね合いが非常に難しいというのが一つございます。\nそれから、訓練の実施でございますけれども、やはり何かをやるときには検証をするために訓練を実施するということは当たり前ではないかということで、避難所訓練を一昨年あたりから進めているわけですけれども、昨年はかなりの学校でやっていただいたということです。確かに５８校中１５校ということになりますと、決して多い数ではございませんけれども、この辺も着実に進めていくしかないかなということでございます。\nそれから、２番目の防災広場でございますけれども、これは、先ほどお話がありました、用地があっても、それが高くて買えないとか、適当な広さがない、３００m2以下であるとかというような中で、適切でない。もう一つは、適地に広いものが出てこない。私どもが今一番欲しいのは、戸越と中延四丁目ですか、たしかあそこら辺の危険度が一番高い、荏原地区の部分でございますけれども、住宅密集地ということで、なかなかまとまった形での広さのものが出てこない。そういう形で、ある程度拠点拠点で、どうしても住宅密集地というような形で土地を求めていきますので、そういうところはまとまったものがなかなか出ないという状況になって、平成５年以降購入する機会がなかったということでございます。いろいろな形で私どものほうに情報がまいります。なかなかそれが合致したものにならないということで苦慮しております。\n最後に、災害弱者でございますけれども、全部で３４町会の２２町会、５６町会ばかりが今取り組んでいるわけでございます。町会としては全部で２０５町会ございますので、約４分の１の部分が取り組んでいるという具合に考えております。これは助ける側の確保というのが非常に難しいということで、やはり地域の中で若い人が中心になって、いろいろな形で町会・自治会にお手伝いをしていくというような体制づくりができませんと、口先だけのものになってしまうということで、そこら辺の体制づくりというのに大変苦労しておるところでございます。\nただ、私どものほうもいろんな形でこの部分についてはＰＲをしております。そういう意味では、今年あたりは地域全体、連合町会という一つの範囲の中で、全体が取り組んでくれるようなことも話としては聞いております。なるべくそういう形で取り組む町会、何しろ早く手をつけるというところで手を挙げてほしいということで，私どものほうとしては今お願いしているので、もうしばらく時間の猶予をいただきたいということでございます。"},{"i":87,"speaker":"堺委員","text":"状況は分かりました。災害弱者についても、今おっしゃったような，早く取り付ける、せっかくいい計画、必要な政策なので、どうしてもこれは財政としても組んでやらなければいけない。現状としては確かにいろいろな難しい面があるのは十分承知しております。そういう意味で、毎年言われているんですが、各連合町会単位の中学校とか、学校を使って、それなりの団体で当然やってもらうことになりますけれども、その都度その都度、口がすっぱくなるくらいの要請をしていかないと、町会の訓練も分かっていても、なかなか手がつけられない、難しい。先に考えると、なかなか手がつけられないということがあるのかなという気がするんです。そういう意味で、早く手をつけるように各委員会に対象者がいるのでこちら側も努力をしていただければなと思います。\nそれから、学校の避難所訓練についても、学校と地域で、さっきもおっしゃったようですけれども、そういうことで、これもやっぱり災害弱者と同じで、早く手をつけていかなければならないことだろうと思うんです。学校が特に避難所として指定されていない施設であれば話は別なのかもしれませんけれども、学校が避難所、なおかつ避難所としての機能も充実させていくという、ですから、一応何かあればそこでみんなが来る体制になる。そういう意味から言うと、地域外での町会の協力体制における訓練とか、必要なことだと思います。その辺もやっぱり大変なことだと思いますけれども"},{"i":88,"speaker":"石田副委員長","text":"部長がいらっしゃらないので、こんなことを聞いていいのかどうかわかりませんが、せっかく事業部制を引かれて、書式のことでちょっとお聞きをしたいんですが、この事務事業表を見させていただいて、事業部制だとか、二つが一つになったり、いろいろな形をとられたんですが、課ごとで書式がばらばらですよね。これは庁舎の中でも一本化を図っていこうとか、今努力をされていて、やっていく中で、以前にも事項別明細書がばらばらだなどという話もしておったんですが、統一化を図ろうという形のものがあったはずですが、せっかくここで事業部制を引いたときに、統一をしてやろうという話がなかったのかどうか、ちょっとお聞きしたいと思います。"},{"i":89,"speaker":"宮地区民課長","text":"事務事業概要をつくるための検討会もつくりまして、部長のもとに、なるべく統一した様式にしようということで、項目は統一するところまでいったんですけれども、予算に、目的に、根拠に、執行実績という、そこまでいったんですけれども、あとは長い間の見やすさとか、各課の取り組みのまとめ方がどうしても崩せなくて、本当に申し訳ありませんでした。\nもうちょっとこれを突き詰めていかなければいけないんですけれども、みんなそれは承知しておりまして、今回はちょっとフロッピイの枠を決定してつくってしまったところがすごく多くて、もう一回組み直すのはばたばたしていてということもあったので、大変申し訳ないんですけれども、次回、今まで手づくりでまとめていたものですから、きちんとしたフォーマットでやっていかれればというふうに思っていますので、もうちょっと時間をいただきたいと思います。"},{"i":90,"speaker":"石田副委員長","text":"今のはお願いだけをしておきます。\nもう１点は、原委員もおっしゃっていたんですが、事務事業評価も始まりますし、費用対効果をどういうふうにするのかというようなところを、行政評価を含めて、必ず始まっていくと思うんですが、その中で皆さんがいろいろ言ったので、個々に言ってもあれだと思うんですが、例えば産業振興の１１ページだと、しながわ産業ニュースとか、戸籍住民課で言うと、６ページ、出生率のことが書いてあると思うんですが、例えば結婚している世帯の出生率がどのぐらいだとかというのは、あるところで見たことがあるんですけれども、これだと0.８８ですが、結婚している世帯だけの方をとると、こんなはずはないはずなんですね。これもイメージアップ効果というのがあると思うんですが、イメージで0.８９で、品川区って１人っ子が多いみたいなところがあるけれども、多分２人ぐらいの数字が出てくると思うけれども、そういう形のイメージアップ効果とか、あとは、区民まつりがこういう形でいいのか。産業振興でもいろいろなお金を、例えばにぎわい創出事業に出す、それに対する経済効果がどこまであったのかとか、費用対効果だけではなくて、経済効果がどこまであったんだというところまで突っ込んで調べるとか、あとは、防火協会に対する助成金とか、こんなのは何もなければ、やめてしまえとか、そういうところまで突っ込んだものを、ここで評価が始まってくるわけですよ。それぐらいの、最初に委員長が、重点を言ってくださいという話をしていたんですけれども、そういうところのことが一つも書いてないという感じのところがあって、そういうところを一つひとつどこまで突き詰めるか、イメージアップ効果なのか、経済効果なのか、あとは、長く事業をやってきたことに対して一つメスを入れるのか、そういうところをどういうふうにお考えなのか、これを聞きたいなと思います。"},{"i":91,"speaker":"宮地区民課長","text":"事務事業評価については、今年度スタートするということで、既に自分の課で何本、企画ゲージが何本ということで、１０本近い本数を各課が挙げまして、それについては、まずはやってどうなのかということは、当然効果を見るためにやるわけですから、インプットとアウトプットを見て、本当にそれが効果のある事業になっているかというのはきちんと検証できるというふうに思います。\nそれがないと、どういうふうにしていったらいいか。今までは並べていただけですから、わからなかったんですけれども、そういう意味ではこれからの見方というのは、そういう形に、経済効果、それから新しい視点でイメージアップ効果というのもありますね。経済だけではない部分もありますので、そういう姿勢で見ていくのが大切だと思いますし、また、そういう視点で事務事業概要をどこまでまとめていかれるかというのもあるんですけれども、課題として考えていきたいと思います。"},{"i":92,"speaker":"石田副委員長","text":"事務事業概要はそれにしておきますが、もう一つだけ。\n最後に、保険年金課の前納の差額ですけれども、これの考え方だけは教えていただきたいんですが、前納分の割引がありますよね。どこでも割引は今はなくなっていますよね。今はあるんだけれども、多分2,０００万円ぐらいだと思うけれども、2,０００万円以上あるのかな。ここは前納をやめる方向なのかどうか、教えていただきたいと思います。"},{"i":93,"speaker":"小野年金制度担当課長","text":"年金の前納の割引率の、どういう根拠に基づいてこの割引ができているかということについて、国のほうの制度だということで、私のほうでこれがどういうふうな根拠に基づいてというところまで、現在のところまだ勉強不足で、把握をしておりません。\n来年度以降につきましては、年金の事務が大幅な改正があって、主要事務については国のほうに移管になるということですけれども、こちらのほうの前納の割引について、これを廃止するのか、あるいはそのまま残すのかということについては、現在のところは廃止をするという方向での情報は得ておりませんで、引き続きこの形でというふうに考えております。"},{"i":94,"speaker":"南委員長","text":"ほかに、ご質疑はよろしいでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":95,"speaker":"南委員長","text":"以上で、区民生活事業部に関する質疑を終了いたします。\n２時間半近くかかっていますので、若干休憩をとって、また再開したいと思います。\n暫時休憩いたします。\n○午後３時２４分休憩\n○午後３時３５分再開"},{"i":96,"speaker":"南委員長","text":"休憩前に引き続いて、区民委員会を再開いたします。\n────────────────────────────────────────────\n(2) 環境清掃事業部"},{"i":97,"speaker":"南委員長","text":"(2)の環境清掃事業部の事務事業概要についての説明をお願いいたします。"},{"i":98,"speaker":"野本環境清掃事業部長","text":"それでは、お手元に配付してございます事務事業概要、平成１３年度版の環境清掃事業部のものをご覧になっていただきたいと思います。\n１ページをお開きいただきますと、環境清掃事業部の組織概要ならびに人員配置状況が出てございます。ご案内のように、環境清掃事業部、清掃事業が平成１２年４月に区のほうに移管をされまして、従来ありました保健部の中の環境課と清掃事業を合体させまして、環境清掃事業部といたしまして、環境課が従来どおりの環境関係の業務をし、この中にございましたリサイクル部分を清掃事業と合体をさせて、清掃リサイクル課という形にして、一本化をしてございます。\n平成１３年度はＩＳＯが具体的に立ち上がって、認証に向けて、既に今日と明日が予備審査という格好でＩＳＯの認証機関のほうから今ヒアリングを受けている最中でございますけれども、そういうような年に当たるということで、環境課一本でやっておりましたＩＳＯの部分について、担当課長を配置して、若干増強をさせていただいているという格好になっております。\nそれから，清掃リサイクルのほうも、従来は清掃リサイクル課という形でやってまいりましたけれども、今年度割合大きな事業にあります、一般家庭における各戸取り収集であるとか、今までどうしても東京都の影を引きずっていた部分がございますので、品川清掃事務所、荏原清掃事務所というような形で、かつて東京都４３清掃事務所がございました。その中の４３分の１ずつがそれぞれ荏原と品川にあったと、こういうような形をできるだけならして品川区の清掃事業に持っていきたいというような部分がございます。そういうような部分がございまして、調整担当課長というものを置いて、できるだけ事業所の業務内容等のすり合わせ、考え方等について１本化をして、早く品川区の清掃事業という形で定着をさせたいということで、この部分についても人員を配置していただきました。\nなお、品川清掃事務所、荏原清掃事務所は、清掃事業の実際のメンバーの業務を担うという格好で、組織的には従来のままできております。\n配置状況等は、お手元に記載されているとおり、トータル３７８名と、かなり膨大な人員になってございますけれども、これは両清掃事務所の実際に住民の方々のところに行って廃棄物を収集をするという実務をやっている職員が多いということで、ここの中の技能１が２４８名、それと、運転業務というような形で、この中が実際の収集をやるということで、そこの部分が多いんだということでご理解をいただければありがたいと思います。\nなお、区民委員会と、それから、先の議会の中で決定をいただきました清掃リサイクルに関しては、特別委員会の付議事項という格好になっておりますので、今回の事務事業の各課ごとの説明につきましては、環境課を中心とさせた説明にさせていただきたいと思いますので、よろしくお願いをしたいと思います。\n私のほうからは、以上です。\n引き続き、環境課長のほうから環境課についてご説明をさせていただきます。"},{"i":99,"speaker":"金井環境課長","text":"それでは、お疲れさまのところでございますので、簡単にご説明をさせていただきたいと思います。\n２ページをご覧いただきたいと思います。ＩＳＯ担当課長を初めといたしまして、２係３担当主査制の２２名で事務を執行しているところでございます。\n７ページをお開きいただきたいと思います。具体的な事務事業でございますけれども、環境保全のＰＲといたしまして、使い捨て型社会から循環型社会へ転換していくための、区民、事業者への働きかけ、あるいは啓発活動として、環境保全のＰＲを行っております。環境リサイクルフェア、あるいは地域のイベントへの参加、環境レポーターによります自然環境調査などを実施をしているものでございます。これにつきましては２９ページにも載せてございます。\n８ページでございます。先ほど部長からもお話がございましたけれども、環境ＩＳＯの認証取得でございます。これにつきましては、今年度の環境保全への取り組みとして、区としての目玉の一つでございます。５月に運用を開始いたしまして、今年度の取得を目指しまして、全職員が現在日常の業務の中で省エネ、省資源等の運用に当たって取り組んでいるところでございます。また、議会の皆様方より５月にご協力の意思として、議長より文書をいただいておりまして、心から感謝を申し上げる次第でございます。なお、引き続きご協力のほどお願いをいたしたいと思います。\n次に、１０ページでございます。大規模な事業などの環境アセスメントに対します調整、あるいは区民の生活環境保全のための、工場などから発生をいたします騒音、振動、悪臭などの公害規制、指導等の改善を行っているところでございます。\n１３ページをお開きいただきたいと思います。同様に、建設作業に伴います公害関係の規制・指導の実施でございます。\n１４ページをお開きいただきたいと思います。公害関係の苦情・相談等でございますけれども、近年におきましては、工場や建設作業の騒音、振動のほかに、クーラーの室外機、あるいはカラオケ、マンション内のさまざまなトラブルなど、近隣騒音などが増加をしている傾向にございます。なお、基準などに違反している場合につきましては、改善・指導を行っているところでございます。\n続きまして、１５ページから２８ページにわたりましては、区が実施をしております法令あるいは独自も含めまして、さまざまな環境調査、測定、あるいは監視業務でございます。１５ページの大気汚染調査でございますけれども、これにつきましては、大別をいたしまして、一般の大気の調査と、自動車の排出ガスの調査、２点ございます。一般の大気調査につきましては、年間を通じて行っております固定測定と、固定測定を補うための、毎年場所を変えての移動調査、これは１５ページにございますが、さらに区内全体を把握するために、区内１kmメッシュごと、約２７地点でございますが、１６ページでございますけれども、簡易測定調査もあわせて３種類を行っているところでございます。\n１５ページの下、環境基準の枠の二酸化窒素の１時間値の１日平均値が0.４ｐｐｍから、0.００６ｐｐｍとなっておりますが、0.０６ｐｐｍの誤りでございます。大変申し訳ありません。訂正をお願いしたいと思います。\nなお、調査結果につきましては、ご案内のことと思いますけれども、二酸化硫黄関係は、ここ数年大きな変化はございませんで、基準は達成しております。二酸化窒素、ＮＯ2といわれておりますけれども、基準をクリアできていない状況が多くございます。これは１９ページに載せてございますけれども、これにつきましては、工場などからの固定発生源につきましては大分改善をされてきております。問題は、自動車による移動発生源でございます。現在の大気汚染の中で最も問題になっておるところでございます。ＮＯ2の７５％は自動車の排出ガスといわれております。ご案内のとおり、自動車の排出ガスの抑制につきましては、都が国に先駆けましてディーゼル車の規制、あるいは低公害車への転換など、積極的に動き出しているところでございます。これについては、２２ページに若干載せてございます。\n次に、２３ページをお開きいただきたいと思います。水質関係でございます。水質調査といたしましては、目黒川３カ所、立会川１カ所、運河で２カ所、海域が１カ所、計７カ所で、各々年６回採水をいたしまして、調査をしているところでございます。\n次、２５ページでございます。地下水の関係につきましても、区内４カ所で実施をしてございます。これについては、民間の井戸を定点としてお借りをしまして、水質関係の調査をしているというところでございます。なお、水質関係につきましては、区の衛生試験所のほうに分析をお願いしているところでございます。\n次に、騒音・振動の調査でございますが、自動車騒音・振動調査につきましては、主要幹線道路の沿線１２カ所で実施をしているところでございます。\n２７ページは、航空機の騒音調査でございますけれども、都の委託事業として実施をしておりますが、八潮中学校、都立工業高等専門学校の２カ所で行っております。羽田空港の沖合移転が完了しまして、八潮上空の飛行が大幅な減少ということで、この表にございますように、騒音も低減をしているという状況にございます。\n２８ページでございます。そのほか鉄道騒音・振動関係でございますけれども、新幹線などの調査も実施をしているところでございます。\n２９ページの、環境情報システムということで、各種の測定結果、あるいは自然環境調査などの情報を地図上に落とし込みまして、区民に分かりやすい形での地図情報化をして、現在も提供を行っております。なお今年度につきましては、全庁挙げてのＩＴの精神ということもございまして、インターネットの立ち上げで、現在ホームページを作成の検討に入っております。環境課におきましても、さらにこのシステムを生かしながら、より区民の皆様に見ていただけるように、現在内容を精査、あるいは検討をしているところでございます。\n以上です。"},{"i":100,"speaker":"南委員長","text":"説明が終わりまました。\n皆様からのご質疑を伺いたいと思います。\n〔「なし」と呼ぶ者あり〕"},{"i":101,"speaker":"南委員長","text":"なしという声がありますけれども、なければ、私がお聞きしたいと思います。\n１５ページの真ん中辺に表が書いてありますけれども、どういうふうに理解していいのか全然わからないので、教えていただきたいんですが、平成１１年度、平成１２年度の一番左のところに、評価値というのがありますね。二酸化窒素が年々増えていて、先ほどの説明では、車からの排出ガスが大きな原因だとおっしゃっていましたけれども、評価値というのはどういうふうに捉えたらいいのかというのがちょっとわからないので教えていただきたいと思います。"},{"i":102,"speaker":"金井環境課長","text":"この評価値の考え方でございますが、次ページの2)、除外値というような表現がございます。長期評価ということで、2)のところに書いてございますけれども、年間の１日平均値のうち、高いほうから２％の範囲内にあるもの、３６５日の測定値がある場合は７日分の測定値を除外した後の最高値を環境基準として比較をして評価をする、こういう内容でございます。"},{"i":103,"speaker":"南委員長","text":"私も、今説明してなかったところは読んだんですけれども、なおわからなかったので、改めてお伺いしたいなと思ったんです。"},{"i":104,"speaker":"野本環境清掃事業部長","text":"簡単にご説明をさせていただきますと、分かりやすいのは、清掃工場などは３６５日ずっとやっておりますと、環境基準に一瞬たりともオーバーしてはいけないというと、６００ｔ工場ですと、５４０、５５０ｔぐらいしか燃やせないぐらいじゃないと、結局、いろいろな運転状況というのが、原材料などどこの工場でもそうなんですけれども、ちょっとしたブレで日最高値で針がピョッと触れることがあるんです。それを一切出さないということになると、非常に運転条件がシビアになってしまうんです。それは、そんなに神経を使わないと環境上問題があるかというと、そうでもないよということで、そういうようにイレギュラーで出たものを、一応２％ぐらいはカットしましょうよというような考え方で、長期のものについては見ていくというようなぐらいでご理解をいただければよろしいのではないかなというふうに考えております。"},{"i":105,"speaker":"南委員長","text":"いいんだか悪いんだかというのが、ちょっと不安になってくるんですけれども、あまりシビアに気にする必要もないのかなというところは、それはそれとして理解はできますが、年々大気汚染のところは深刻な状況になりつつあるというのが、一時期下がったものの、またカーブが右肩上がりだというところでは、あまり深刻にならないよというところだけを捉えちゃうと、何か不安になりますので、改めて疑問を持ったんです。それはそれとして理解は一定程度できました。"},{"i":106,"speaker":"原委員","text":"先ほど説明の中で自動車の排出ガスのことで、東京都絡みの話がありましたけれども、トラック、あるいはバスについては、装置につきましては、装置が今の段階ではかなり使えるんだけど、東京都に入ってくる車の問題であるとか、これをつけさせることについては、かなり安くなってくるよという話をしているんですけれども、現実、品川区のこういう問題について、既に対応されたものがあるんじゃないかと思うんですけれども、現場がすごいということではないようですけれども、その辺の見通しというか、考え方というか、ちょっと教えてください。"},{"i":107,"speaker":"金井環境課長","text":"さっきも若干触れましたが、東京都の環境確保条例という大変厳しく規制をかけております。当然この規制の内容については、区も車をたくさん持っておりますし、ディーゼル車も使っております。これについては、この条例に基づいた期限までに何とか処置をしないと実際は走れないということになります。さらに、低公害車の導入等々も、これは行政が積極的に進めなさいと。ただ、これにつきましては、費用がかなりかかりますので、新しく買ったばかりのものもございますので、それをいきなりというわけになかなかまいりませんけれども、できるだけ導入に向けて私どもも努力をしていくと、こういう姿勢で現在進めてございます。"},{"i":108,"speaker":"原委員","text":"コストは今はかなり高めだそうですけれども、その辺は、例えば品川区内にある同業組合とか、化学業界のところがとりわけ利用があるわけですが、東京都絡みのところもありますけれども、そういったところでは、情報的にはどういうふうな情報をつかんでいらっしゃるのか。"},{"i":109,"speaker":"金井環境課長","text":"基本的には、その辺の問題について、東京都のほうで言っていると思いますし、私どもには特に値段も含めまして、今後どういった方向で、どのような方針で進めていくのかというような問い合わせは直接的にはきてございません。ただ、東京都のほうは助成としては低公害車の融資でありますとか、そういった制度は幾つか持っているようです。事業者に対します車の融資、あるいは個人向けの限定した車の、本当に低公害車といわれる電気ですとか、天然ガスとか、一部だけですが、これらについても助成があるようでございます。\n先般テレビでもやっておりましたけれども、トラックの運送業者関係については国庫補助のそういう制度があって、それが予算的には国の補助の枠が非常に少ないとか、そういったことも話題になっておりますけれども、国も都もそういった制度を考えているようですけれども、その辺の情報しか私どもはつかんでおらないという状況です。"},{"i":110,"speaker":"石田副委員長","text":"これを見て、環境というのはこんなものかなと思うんですけれども、規制ばかりですね、まず。数値をクリアすることばかりとか、環境が守れるかみたいなことばかりなんですが、せっかくこういうことをやっていかれるのであれば、事務事業概要の中に、例えば２９ページみたいな自然環境調査で、ぱっと見た感じでは、昆虫ども増えているなとか、そういうところをもっとアピールをするというか、せっかくこれだけ規制をかけてきた中だけれども、それによって環境がよくなって、こういう効果がありましたみたいな、アピールをするようなものを、今年はこういうところを積極的にアピールしていきすよ、よくなったからというようなものが幾つか載ってくると、見ているほうも、聞いているほうも、ただ規制ばかりで、その数字をクリアするだけというような見方ばかりになってしまうと、これから環境を考えていく上にはよくないんじゃないのかなと思うんだけれども、その辺。"},{"i":111,"speaker":"金井環境課長","text":"大変難しいわけでございますけれども、特に大気の場合は、区レベルでどうかという問題は、非常に環境の問題が多くございますので、区が規制をしたりという権限は非常に少ないです。自動車にしてもそうですし、工場の一部とかは規制で私どもは改善とか、そういうことをやっておりますけれども、そういう意味では、なかなか即改善しましたよという結果が、やはり国レベル、あるいは大都市圏レベルと、こういったレベルで規制をかけたり、長年の積み重ね、これはＩＳＯもそうです。事業者とか、その積み重ねがないとなかなか難しい。ただし、それは、委員ご指摘のとおりだと思います。私どもも、例えば公園なども多く土地を買ったりすれば、それだけ自然が増えるわけでありますし、また、屋上緑化とか、そういった緑関係も積極的に進めるようになっておりますので、そういった観点とも含めまして、環境システムの中に、検討の中に私どもも公園等も含めて入れていきたい。少しでも何かそういう、おっしゃったような意見も踏まえて取り組んでいきたいという気持ちで取り組んでまいりたいというふうに思っているところでございます。"},{"i":112,"speaker":"本田委員","text":"今日は環境デーということで、いみじくも環境の報告を受けたわけですけれども、総論で言うことはないんですが、水質の問題で、品川区では立会川が東京都のワーストに入って、何とかしなければならないというのは、議会の中でも取り上げている問題ですけれども，この文章では、平成１２年度は勝島のカルバートの中から、カルバートとは書いてありませんけれども、運河の水を測って、流した。平成１４年度はＪＲの地下水を持ってきて流すということが書いてありますけれども、本年度はどういうことをやるのかということが書いてないんですけれども、上段のほうに、水質調査の問題では、立会川の問題も、下水幹線が、そもそも月見橋のところからあふれるような仕組みになっているということ自体が原因になっているわけで、これを直さない限り、どこから水を引っ張ってきても、大水が出て、下水道があふれたときには、その後は悪臭がなかなか消えないと、こういうことを繰り返しているわけです。これは大田区においても、呑川とか、同じような状況を繰り返しているわけですけれども、そういう点で、本年度どういう改善をやっていくのか。また、周りの住民の皆さんに協力を求めるのか、そういうことをちょっとお聞かせいただきたいと思います。"},{"i":113,"speaker":"金井環境課長","text":"端的に言いますと、引き続き昨年と同様に導水実験を、昨年と同様な、カルバートから導水をしまして上流から流すと、これは同じようにやっていくという方向です。\n効果でございますけれども、先般、立会川の浄化の関係の打ち合わせがございまして、お聞きをしました内容によりますと、ＤＯの溶存酸素量の効果はかなり見られたというようなことがございました。悪臭の原因の効果というのが原因究明がなかなか難しい。ただ、この導水実験の期間においては、全般的に悪臭については苦情が少なかった。ただし、その少ない原因が明確に見えなかったということがございます。\nそういう意味におきましては、全く効果がないということではないんですが、溶存酸素量等についてはかなり効果があるだろうというふうに言われております。\n特に今年度におきましては、悪臭が出た日に地域の付近の住民の方から連絡をいただいて、すぐ調査をした。それは悪臭の原因をつかむために、定期的に調査をするだけでなくて、悪臭が出たというときに、地域の住民の力を借りて、連絡など、これから調整をすることですが、そのときに調査をすると、そのとき出ていた悪臭の原因がある程度つかめてくるんじゃないか。それが確実につかめるかどうかわかりませんけれども、そういう新たな目標を持ってやっていきたい。これが一番大きな目標でございます。"},{"i":114,"speaker":"本田委員","text":"細かい話になって大変恐縮ですが、先般私のところに立会川のそばの人から手紙がありまして、今、区を挙げて立会川の浄化問題を取り上げているときに、洗濯水を川に流し込んでいる。けしからん。こういうことがあっていいのかというような手紙がきたんです。あそこは枝管といいますか、細かい管が立会川に出ていますので、あれはまだ使われているんですか。全部止められて、沿線の下水道管に入っているように私は理解していたんですけれども、そういう細かい管が立会川に、月見橋の上からの幹線のものだけじゃなくて、周りに相当数の管が川の壁のところに出ているんですが、あれは使われているんですか、どうなんですかということと、そうであるならば、地域住民の皆さんに、行政はこうやっているよというだけではなくて、一緒になって立会川を浄化するために、自分たちもどう努力するかというような、町会とか、商店街とか、皆さん方に訴えて、全体としての運動にすることが私は必要じゃないかなと。キャンペーンを張るときに、近所の町会に呼びかけて、お手伝いを願うというだけではなくて、そういうふうに思っているんですけれども、構造上、立会川の枝管というんですか、これは所管外になってしまうのかな。"},{"i":115,"speaker":"金井環境課長","text":"詳しくは存じておりませんけれども、一部つながっているものもあるというふうなことは聞いておりますけれども、あそこのところなのか、それとも海側のところなのかというのは、申し訳ありません、明確にお答えできませんけれども、いずれにしましても、下水道河川課で調査をしないと。一部どこかが入っているようなことはちらっと聞いたことがございます。"},{"i":116,"speaker":"本田委員","text":"所管外になっているかと思うんですけれども、環境を保全するというか、いい環境にしていくというのは、行政だけではなくて、住民も、我々も含めて、いろいろな角度でできることを協力し合うというのが第一になるかと思っているんですね。立会川の浄化につきましても、私はその点がちょっと欠けているんじゃないか。これまでの取り組みの中で。だから、行政は一生懸命やっていますと。協力してくださいというような姿勢が強いのではないかというふうに思うんです。時々ごみをポンと朝投げて、川に浮いているときもありますよね。こういう本当に嘆かわしいなという感じをするときがあるんですが、立会川の問題で申し上げましたけれども、環境をどう保全するか。もちろん区だけではできないという、課長のご答弁がありました。国や首都圏、大きなレベルでやらなければならない。しかしながら、自分たちの身近なところからどう環境をよくするための努力をしていくか。小・中学生を含めまして、全区民挙げて、そういう観点というものが今求められている。ＩＳＯを取るのもそうだろうというふうに思っているんです。そういう点で、立会川の浄化問題については、洗濯水を流し込んでいるのがいるというので、私には抗議をしているわけじゃないんだけも、これでいいのかという手紙をいただきまして、困ったものだなというふうに思っているところなので、ぜひそういう観点で取りんでいただきたい。要望しておきます。"},{"i":117,"speaker":"堺委員","text":"２２ページの大気汚染対策の車の件ですが、恥ずかしい話になっちゃうかもしれないんですけれども、２２ページの大気汚染対策で、東京都が特に自動車対策に力を入れて、窒素酸化物の規制強化にとどまらず、粒子状物質についても規制を追加し、ディーゼル車に対してＤＰＦの装着を原則的に義務づけた。こう書いてありますけれども、これに関連して、庁舎内の全自動車の中で、この下に低公害車についてありますね。昭和６３年度に初めて環境課に導入して、現在は４３台あるけれども、今後は低公害車についても積極的に導入していくというのと併せまして、全体的には車の、区としての考え方、この形でいけば、どんどん低公害車を入れていって、東京都で一斉強化するディーゼル車に対してはなくしていくんだと。そういう流れになっていくんだろうと思うんですけれども、その辺の考え方を１つ教えていただきたい。\nそれから、今日は説明はないんですけれども、３７ページに品川清掃事務所、３８ページに荏原清掃事務所、それぞれ作業計画自動車台数で、品川清掃事務所では５１台、荏原清掃事務所では３７台、車の種類は違いますけれども、こういう車は、低公害車の方針に抵触するものではないんでしょう。ディーゼル車というか、そういうのもこの中に入っているんですか。\n仮にあるとすれば、東京都は一斉強化するわけですから、清掃事務所のほうでも対応を考えていかなければならないですね。その部分。計画的に今後、東京都の言っている方向に進めていくとどういう形になっていくのかどうか。\nそれから、２２ページの2)に、冬期の自動車交通量対策について、庁有車について乗用車２割、貨物車１割の削減を目標としているとあります。清掃に係わる車は削減されると困っちゃうと思うんです。そうでないものについては、こういう目標を掲げてやっていくということだろうと思うんですが、その辺の整合性を教えていただければと思います。"},{"i":118,"speaker":"金井環境課長","text":"まず、庁有車は１９４台がございますけれども、このうちディーゼル車が清掃車１２台も含みまして、４２台ございます。この４２台の中には、例えば外を走る自動車でないもの、野球場の整備のためのものもディーゼル車としてカウントしますと４２台。外を走れる車、ナンバーがついている車については３５台ございます。ディーゼル車の規制にひっかかるのは、この３５台関係だというふうに認識してございます。\n現在、低公害車は、そのうちの４３台導入済みでございます。私どもで車検の状況も分かっておりますので，そのときには、買い替え時には低公害車の、車検ですべて、どういう内容か、バトル車か、乗用車かというのが分かっておりますが、それで大体２０年、３０年で買い替えの時期ということで、各課が買い替えをしたいといったような場合は、それについて基本的には低公害車の導入をするということになってございます。\n計画的にどうかというお話でございますが、ディーゼル車につきましては、先ほどご説明しましたように、平成１５年１０月から走れなくなりますので、それまでに、排出物の低減装置であるＤＰＦを付けます。先ほど２００万円とか４００万円で高いという、原委員のお話もございましたけれども、それは必ず装置を付けるか、買い替えなければ走れない。これはよく承知をしておりますので、それまでにはディーゼル車については何らかの措置をとっていく。そのほかについてはできるだけ買い替え時に、私どもは今６種類の低公害車の導入、これは大都市圏を含めまして、電気自動車ですとか、天然ガス車、メタノール、あるいはハイブリッド、ＬＰＧですとか、７都県の指定の低公害車というのがございます。こういったものの中から選定をして、車の買い替えを導入をしたいというふうに思っております。\nもう１点は、今調査をかけておりますが、今ある乗用車を、例えばもっと小型にできないか、本当に必要かどうなのか、隣の課と調整して、２台あるのを１台に乗れないかとか、もしそういう調整ができないなら、なぜ調整できないかとかということも、各課に全部流してあります。そうしたこともやりながら、どうしたらこれから計画的に、環境に負荷の低減、次に自動車をできるだけ使わないようにする。あるいはバイクに切り替えられないか、自転車に切り替えられないか、こういう質問も、今アンケートを出させていただいております。そういう形でできるだけ車を使わないような形で、使っても、小さい車、さらに低公害車というような形で鋭意進んでいく予定でございます。\n冬期でございますけれども、庁舎内の各所属に対しまして、自動車の収容規制を求めまして、その収容状況の結果について報告をしていただく、こういう目標を掲げまして、そういう形で取り組んでいるというところでございます。\nさらに、区民に対しましては、ここに書いてあるようなことで実施をして、キャンペーンとか、あるいは広報しながわのページですとか、こういうことで抑制のための要請をしているというところでございます。"},{"i":119,"speaker":"堺委員","text":"車のほうは分かりました。平成１５年１０月から使えないと。あと２年ですよね。その２年間の間に、これから始まるわけですけれども、装置を付けてもだめだということなんですか。"},{"i":120,"speaker":"金井環境課長","text":"装置をつければ走ってもよろしいということでございます。いずれにしましても、低減の何％というのが決まっておりますので、そういう装置を付けるか、低公害車に買い替えないと走れないということでございます。基準がございますので。"},{"i":121,"speaker":"堺委員","text":"区としてはどういうふうにする予定ですか。"},{"i":122,"speaker":"金井環境課長","text":"まだ具体的には、いずれにしても、費用対効果の問題が出てまいりますので、買い替えの時期にうまく当たって、低公害車で安い車のほうがいいのか、あるいはそのときに装置を２００万円なり３００万円かけて装置をつけるほうが効果がいいのか、その辺を勘案して決めていきたいというふうに思っておりますので、今はまだ具体的にこういうふうにするというのは、これからでございます。先ほど言いましたように、そういう場合に、小型にできないかとか、バイクにできないかとか、１台でも２台でも少なくなれば、またそういうことの調整もできますので、そういうことも踏まえて、もう少しお時間をいただきたいと思います。"},{"i":123,"speaker":"堺委員","text":"その辺が、さっきの費用対効果というのがあろうかと思いますので、研究していただいて、全体の流れとしては、環境にやさしいまちづくりに、環境ということが先走ってきますから、区が中心的な役割を果たしていくという意味でも見守りたいと思います。率先して対応していかなければならないということが課せられてくると思います。そういう面で低公害車の４３台、６種類もあるんですかね。さっきの冬期の乗用車２割、貨物車１割と全体で目標を削減をしていく中で、一つひとつ事業部制で、例えば区民生活事業部で仮に今５台使用しているとすれば、冬期は３台使用して、２台は使用してはいけませんよと、そういうように各部ごとで目標を、環境課で設定をして指示するのか、全体で削減の数に達成すればいいということなのか、対応の仕方を考えるとき、それは。"},{"i":124,"speaker":"金井環境課長","text":"今までは目標値、全体という考え方でございますけれども、今後は、ＩＳＯの取得ですと、ガソリン車、車の抑制というのを正式にマネージメントシステムの中で何％削減とか、具体的にこれから出てまいりますので、そういった中では今度きちんと、今車の調査もやっております。そういったことも含めて、これから、冬期だけでなくて、普段からきちっと取り組むような方式を考えていきたいというふうに思ってございます。"},{"i":125,"speaker":"南委員長","text":"以上で，質疑を終わってもいいでしょうか。\n〔「異議なし」と呼ぶ者あり〕"},{"i":126,"speaker":"南委員長","text":"では、事務事業概要を終了いたします。\n────────────────────────────────────────────\n４．その他"},{"i":127,"speaker":"南委員長","text":"それでは、次の予定表では、行政視察ですが、先に４番のその他をさせていただきたいと思います。その他終了後、理事者の皆さんには退席をしていただいて、行政視察のお話をしていきたいと思います。\nその他ですが、何かございますか。"},{"i":128,"speaker":"辻田防災課長","text":"今皆さんのお手元に配付してございます、風水害初動活動態勢訓練の実施結果ということでございます。６月４日、月曜日から金曜日の８日の間までに１日抜き打ちで訓練を実施するということで、職員に予告をしてありました。それを今日実施いたしました。今日報告しませんと７月になってしまいますので、無理を言ってここに入れて報告させていただくということでございます。\nこの訓練は、職員の危機管理意識、梅雨に向かって集中豪雨の時期になりますので、危機管理意識を持ってもらうよう、常に緊張感を持ってもらうことですね。それから、それぞれの職員の役割、また、技術の向上というようなことを目的とするほか、区民が区の災害対応に信頼感を持ってもらうというようなことを目的として実施しております。\n本日の６月５日、４時半に開始いたしました。\n場所は災害対策本部室、防災課の横でございます。それから、職員の集まるところは土木・公園の各事務所でございます。目黒川、立会川周辺には災害対策職員待機寮の職員が連絡を受けて、河川の状況を見に行くということで、このところが訓練場所になっております。\n訓練の参加者につきましては、１４２名のうち１３７名集まったということで、９6.５％。毎年大体かなり高い率で集まっています。\n区長以下、各課の部長、課長、係長、それから、６km圏内の職員が参集しております。その中で、二行目に建築課というのがございます。この部分は、今年から崖や何かの部分も品川区は少しございますので、そういうところの対応ということで、建築課。それから、地域活動課につきましては、見舞金の支給や何かということの事務が地域活動課のほうに渡されましたので、新たに訓練に参加する。清掃リサイクル課は、既にいろいろな形で災害対応をしているわけですけれども、今回初めて訓練に参加していただいたということでございます。\n被害想定は、朝から雨が降り出して、だんだんひどくなっていく。そういう中で目黒川、立会川が危険な状態になっていく。そこで住民の方々からいろいろな電話がかかってきて、それを職員が対応する。職員が対応できないものは本部の担当のほうでそれぞれを手伝う。みな勉強して、そして答えを出す。それを調査させ、それから、また必要な対策を立てて、現地に出動させるという形で訓練を実施しております。\n５番目として、訓練内容は、注意報、警報時の夜間宿直の対応訓練、これは注意報、警報が出たときに、必要な部課長に連絡をするという訓練でございます。それによって継送網を通じて職員を招集し、すぐこちらのほうに集まるというのが２番目でございます。\nそこで、ある時期から本部を設置しまして、その本部を運営するということの訓練。\nそれから、情報機器、情報伝達の訓練は、目黒川、立会川などで水位が上がってきますと、危険のブザー、警戒のブザーを鳴らします。その際に、ブザーとともに地域防災行政無線、いわゆる地域に配置してあるラッパで、どういう状況にあるというようなことを皆さんにお知らせするということでございます。\n(5)図上演習のところでは、職員が住民に扮して、いろんな無理難題みたいなことを出してくる。それに対してどういう具合に対応するか。それをつぶさに検証していくということでございます。\n(6)として、現地のほうでは土嚢積み訓練であるとか、各地域に土嚢を配達する訓練、そういうようなことも実施しております。\nそれから、今年は仮排水施設の訓練ということで、目黒川のところに内水を川に放水する、そういう装置がございます。その装置を使って、内水が氾濫してきたということで、その水を目黒川のほうに戻したというようなことの訓練も初めて実施してみました。\n全体的には参加者も参集率も非常に高くて、意識も高い中で訓練が終了したという具合に私どものほうは考えております。"},{"i":129,"speaker":"南委員長","text":"この報告についてのご質疑ありましたら、どうぞ。"},{"i":130,"speaker":"原委員","text":"これ、急に集まってくださいという連絡を電話か何かでしたわけですよね。どういう形で皆さんは招集してきたのか、時間的なもの。"},{"i":131,"speaker":"辻田防災課長","text":"基本的に部課長、係長、役を持っている係長は、どんなに遠くても来るようになっております。それから、それ以外の職員につきましては、６km圏内、どちらかというと、品川区在住の職員が多く集まるような形になっておりますので、その辺からまず集まってくる。ところが、遠い人もございますので、どうしても２時間近くかかってしまう。訓練終了間際に来るということもありましたけれども、それもやはり役割を持っている係長でございますので、必ず来なければならない。それは通常の、いわゆる新幹線を利用したということでございます。そのほかに自転車で来たり、地震ではございませんので、車の使用も認めております。何しろ早く来いということで指示を出しておりますので、みんないろいろな工夫をしながら、自転車、バイクというようなことで参集しております。"},{"i":132,"speaker":"南委員長","text":"今の件でご質疑はいいですか。\n〔「なし」と呼ぶ者あり〕"},{"i":133,"speaker":"南委員長","text":"以上で終わります。\n次に、きゅりあんの関係で、上山課長、お願いいたします。"},{"i":134,"speaker":"上山総務部副参事","text":"特に資料等はご用意はしておりませんけれども、総合区民会館、いわゆるきゅりあんでございますけれども、改修についてご報告をさせていただきます。\n総合区民会館でございますけれども、来年の夏に大ホール、イベントホール、小ホールなどの改修の計画をしております。日程的には、大ホールの場合、平成１４年７月１７日から９月１０日を考えております。委員既にご存じのとおり、施設予約につきましては、１年前からの予約となっております。今年度、これから実施設計ということで、具体的な内容につきましてはまだ決まっておりませんけれども、施設予約との関連もありますので、区民への周知といたしまして、７月１日に発行いたします広報しながわや、これまでの利用団体への案内を近々配送する予定でございます。委員の方々には、広報への掲載に先駆けまして、ご報告をさせていただくと同時に、詳細が決まりましたならば、改めて委員会にてご報告をさせていただきますので、よろしくお願いいたします。"},{"i":135,"speaker":"南委員長","text":"この件でご質疑はありますか。\n〔「なし」と呼ぶ者あり〕"},{"i":136,"speaker":"南委員長","text":"以上で、きゅりあんの改修計画については終わります。\nそれでは、その他のところの３点目ですが、理事者が退席する以前に、この委員会の１年間の活動のテーマがもし特定されていければいいのかなと思いもするので、皆さんにいろいろご意見を伺いたいなというふうに思うんです。その内容によっては、秋に予定されている行政視察の内容、また行く場所についても事前に明らかにどこに行くかというのが決めやすくなっていくと思うんですが、その辺のところではいかがでしょうか。本年度１年間、先ほどご説明いただきましたが、事務事業の概要については、すごく広範囲のところなので、もちろん全部区民生活には大事なところですが，とりわけこの１年間一定程度の幾つかの柱を持って、調査研究、この委員会として一緒に進めていければいいのかなというふうに思っているものですから、皆さんに何かあれば、ご意見を伺っておけば私どもも運営しやすいなというふうに思っているんですけれども、いかがでしょうか。"},{"i":137,"speaker":"本田委員","text":"私は、別に特定のテーマは考えていません。事業部制という新しい制度をつくって、その中で、今日概要説明をいただいた各課の立案の中で、これまでの積み重ねと同時に、改革的なものの考え方で、新しい制度に挑戦をされて、どう区民の期待に応えて、サービス向上につなげていくかということで、各所管のところで努力されているというふうに、今日概要説明を聞いていて私は感じておりますので、委員会としては、時々の問題点等を設けながら、全般にわたって審議をしていくということでいくべきではないか。特別特定のものを区民委員会でこの１年間重点的にテーマにするということではなくて、すべてが大きなテーマだというふうに思っておりますので、そういう運営をされたらいかがかなというふうに私は、今突然の委員長の問題提起ですけれども、意見としてそのように考えます。"},{"i":138,"speaker":"原委員","text":"今、本田委員が言われたとおりなんですけれども、そういう中で課題を持っていこうというふうに考えるならば、２つの事業部を入れると、みんなで１０の課がありますね。その中で今年の課題みたいなものを持っていらっしゃるならば、各課から挙げてもらって、その中で検討できるもの、できないもの、あるいは我々が勉強できるもの、できないものが出てくる可能性もあるわけですね。あえて選ぼうとすれば、そういう形でいいのではないか。確かに総括的にはいろんな問題が含まれていますから、これを取り上げるということはないかもしれませんけれども、例えば地域活動の中では、この課題については特に重要視しているんだよという意向があれば、そういったことで我々も勉強、あるいは努力をしていきたいというふうに思っております。"},{"i":139,"speaker":"南委員長","text":"突然に提起しましたので、皆さんも戸惑っていらっしゃるかなと、今伺いまして思いましたけれども、正副委員長のところで実は今日の午前中、今日の運営に当たって打ち合わせをさせていただいたときに、そういうことで皆さんのご意向を伺っておければ、私たちのほうも運営がしやすいかなというふうに思ったものですから、議題として提供することとしたわけです。\nこれといってなければ、それはそれでよろしいんですけれども、もちろん全般にわたって大事なところですから、一つたりとも優劣というのはありませんので、それはそれで大事なことでいいんですけれども。"},{"i":140,"speaker":"菊地委員","text":"私も、今発言された両委員の言うとおりだと思うんですが、同時に、先ほど申し上げたんですけれども、今不況の中で、実際に区内経済が停滞をしているという状況の中で、もし軸として考えていくことができるのであれば、区内の中小企業、振興を含めたところにある程度的を絞った形で考えることはできないかなというふうな希望は持っておりますので、それだけちょっとお伝えをしておきたいと思います。"},{"i":141,"speaker":"石田副委員長","text":"今正副委員長でお話をさせていただいた、委員長の補足をさせていただきますと、もちろん今理事者の方もいらっしゃって、委員の８名で１年間これをやっていこうという中で、非常に範囲が広い。範囲は広いのは、もちろんそれの中で、私どももすべてにわたって審議をしていこう、そういう形で臨むわけですが、その中でも、委員会を活性化する意味においても、皆様が、今、原委員が言ったように、各課ではこういう課題があるんだ、それにはだれかが受け持ってでも、私は自分のやれる範疇の中で、皆さんが意識付けの中で、このことについては委員会活性化のためにひとつぽんと、今菊地委員がおっしゃったように、中小企業の振興が出てくれば、じゃ、そのことについては、それでその後の行政視察にも入ってくるんですが、そういう形の中で、じゃ、こういうところ、こういうところと、自分で調査をして、そういう形のものを出してこようというほうが委員会が活性化できるのではないのかなというような話を委員長とさせていただいて、皆様に投げかけをしているという状況なものですから、逆に理事者の方がいらっしゃる前でそういう形でやっていきたいということを言ったほうがいいんじゃないですかということで、委員長に今発言をしていただいたというところが、補足をさせていただければ、そういう形でお願いをしたいということです。"},{"i":142,"speaker":"南委員長","text":"それでは、全般にわたって大事なことですので、取り立ててというご意見もありましたけれども、原委員のほうから、各課で抱えていらっしゃる、とりわけ今年度はこういう方向でというポイントがもしあれば聞かせていただきたいということも、出してくださいましたので、その辺を、なければいいんですけれども、あれば出していただいて、そして、その上で、また改めて正副のほうで整理もさせていただければというふうに思っております。もちろん皆さんのご意見も伺っての上ですけれども、そういうことで、今理事者のほうからポイントを伺ってみてもいいでしょうか。"},{"i":143,"speaker":"本田委員","text":"運営の仕方の問題で、今いきなりそういうのはちょっと難しいと思うんです。私先ほど申し上げましたけれども、本年度の予算の中でも、各課で新規事業とか、レベルアップ事業とか、具体的に列記されていますよね。だから、私は、そういう事業がどういう展開を事業部制の中でしていくのかなというふうに、一方では思っているわけです。だから、区民委員会の所管の中でそれを見るわけですから、ほかのところはいろいろな見方もあるでしょうけれども。ですから、ただマンネリに委員会をやっているのではなくて、私は、今年の委員会というのはそういう意味では非常に重要な委員会だし、区民委員会の所管する全部について我々としても目配りをすべきであるというふうに自分では思っておりますので、そういうことで、押し出しどころは新規事業とか、レベルアップとか、いろいろ工夫されたものが各所管課でもあるわけですから、それをちゃんと報告もしていただいて、審議の材料に乗せていただいて、効果的になっているのかどうなのかというような議論をさせていただきたいと、私はそういうことを含めて先ほど発言させていただきました。ただいきなり今課長のところで何かあるかという進め方は、それはちょっと、今の中でまずいんじゃないですかということを１点申し上げます。"},{"i":144,"speaker":"原委員","text":"今の本田委員の言うとおりなので、正副と、課長と、その辺のすり合わせをされて、確かにみんな大事な問題を抱えていると思うけれども、区民委員会としてどこかで目標を持っていかなければいけないでしょうから、そういうすり合わせをしてください。その中で幾つか課題を出されて、我々もこの辺については意見を出しましょう、相談しましょうというような形になると思います。"},{"i":145,"speaker":"南委員長","text":"では、できれば次回までにいけるかどうかわからないですけれども、できるだけ早い時期に、今皆さんからいただいた意見、そして理事者のほうとも調整もさせていただきながら、提示できるように努力をしていきたいと思います。\nでは、一応ここで理事者の責任は解いて、退席していただいて結構でございます。\n〔理事者退席〕\n────────────────────────────────────────────\n３．行政視察について"},{"i":146,"speaker":"南委員長","text":"引き続きまして、行政視察についてを議題にいたします。\nこれは行政視察についての、委員の皆さんのご意見を聞きたいということです。実は、先達って正副委員長会がありまして、そこで議長のほうから、皆さんのご意見をぜひ伺ってほしいということでご提案がありました。その中では、行政視察について、今までは理事者が２人同行しておりましたけれども、それを１名にしたと。二つ目には、経費について、各委員、理事者、書記の経費のところで若干の差が出ているということで、ここは同じ場所に同じ目的で行くわけですので、平準化をしていったらいいのではないかということがありました。３点目については、いつも視察には２人の書記が随行していただいておりますが、１人の場合もあり得ると。そういうことも含めてどうなんだろうかということで、各委員会の中で委員の皆さんのご意見を伺ってほしいという提案がありましたので、行政視察をこの委員会でも、いつの時期とははっきりまだ特定はできませんけれども、これからやっていく予定にしたいというふうに思っておりますので、その辺での取り組み方、あり方、そこも含めてのご意見をぜひ伺っていきたいというふうに思っています。\n皆さんから出された意見を、私ども正副のところでどうこう処理してということではなくて、６月２９日に新たに委員長会が開かれるんですが、そこの場面で、こんな意見がありましたよということを全部漏れなく出して、そして一定の方向を求めていければいいのかなというふうに思っております。そういうことで、行政視察についての一定程度の考え方を皆さんからご意見として伺いたいということで、お諮りをしたいと思います。"},{"i":147,"speaker":"原委員","text":"これは私の個人的な考え方で、皆さんはそれぞれ違った意見を持っていらっしゃると思うんですけれども、昨年の行政視察のときに、ある意味で、今までの行政視察のやり方を、考え方を変えようじゃないかという話になって、目的意識をちゃんと持った形の中で行政視察をして、その報告を書記に頼るのではなくて、参加した方々のご意見をそこに踏まえた形で報告しましょうよというような手法をとったわけです。ですから、今回もそれをもう一歩前進させるという意味で、視察の場所なり、内容的に、今日のお話の中で、課の中でもいろいろな形で出てくるはずですから、そういうようなものを加えて、どういうような課題を持っていけばいいのか、そして、その課題に対して、どこの場所が合致するのかということを調べて行かれる。そしてまた、それについては前もって皆さんと２回や３回の回数を持って委員会を開くなり何なりしてというのが一番ベターではないかなというふうに私は思うんです。\nそれから、理事者のほうの随行は、これは行政のほうで、上の話ですから、私たちがだれにしてくれ、何人にしてくれという話ではないと思うので、１人なら１人で結構じゃないかと思います。\n事務局のほうですけれども、仕事量も大変多い中での視察にはなると思うんですが、私は、大変だろうと思うんだけれども、１人でも大丈夫じゃないか。というのは、ただ、その分、参加される委員の方々の負担が高くなりますから、それが自覚がないと大変だと思うんです。というのは、例えば今まで２人随行されると、１人の人は添乗員の役目をされていて、１人の人は向こうとの折衝をするというような形で役割分担の中で仕事をされていたと思うんです。その添乗員の部分がもしないとすれば、我々が一人ひとりの自覚の中でそうしたことをしっかり守っていかなければならない。向こうとの折衝その他については１人で十分できるのではないかなというふうに思います。したがって、帰ってきた報告についても、我々の中から意見を十分皆さんで精査しながら出しながら、一つのまとめ上げたものをつくり、それを最終的に正副でおまとめいただくという形がいいのかなというふうに、これは私の個人的な意見ですけれども、思っております。"},{"i":148,"speaker":"本田委員","text":"基本的に今、原委員が言われたようなことだと思っているんですけれども、去年の区民委員会では、桜井委員長だったんですけれども、場所や日にちありきじゃなくて、何を視察するかで随分議論があったように記憶しております。そういうやり方で今年の視察は何をテーマにするかというところで、それに見合った場所はどこなんだと。こちらの視察に応えてくれる自治体はどこにあるんだということで探して行ったというふうに記憶しておりますので、そういう方法というのがいいのではないかなというふうに思います。\nそれから、同行者の問題については、私は、１人で全部できるのか、２人がどうしても必要なのか。"},{"i":149,"speaker":"南委員長","text":"書記の話ですか。理事者でなくて。"},{"i":150,"speaker":"本田委員","text":"ええ。理事者は１人でも２人でも、それはさっき原委員が言われるように決めてもらえばいいのであって、テーマによって、ここだと環境と区民税があるでしょう。両方のテーマを持って視察に行くとき、本当はどっちもいたほうがいい場合だってあるけれども、視察の内容が内容だから、１人でいいわというふうになるのか、その辺はよくわかりませんが、同行も実に見合った同行であれば、２人だっていいんじゃないのかなというふうには思いますけれどもね。事務局の方の同行についても、１人でできるなら１人でもいいし、２人がどうしても必要だというのであれば、２人だっていいのではないかなというふうに思います。あまり人数には。それが合理化する意味でどうしても減らさなくちゃならないと。さっきの冬期の車じゃないけれども、どうしても削減の目標にあるんだというのであれば、これはまた検討の余地があるけれども、そうでなければ、視察の実態に見合ったサポート役をぜひやっていただくということでいいんじゃないかなと。\nそれから、報告書の問題は、大変でも正副と事務局でまとめていただくというものがいいのではないかなと思いますけれども、各人が何か書くと、主観がいろいろ入っちゃって、変な種目になっちゃうから、ですから、正副に事務局と一緒になって、完璧な報告書をつくっていただければ、それはそういうことでよろしいんじゃないかなというふうに私は思います。"},{"i":151,"speaker":"堺委員","text":"今、原委員、本田委員がおっしゃっておられたような考え方でいいと思うんですが、理事者については、これは向こうで決めていただいていいわけですから、１名にするか、２名にするか、向こう側の考え方でいいと思います。\n書記については、従来のようなお二人で役割分担をしながらやってもらうという形がいいと思います。さっき実態に見合ったという表現を使われましたけれども、それでいいような気もするんですが、ただ、実態が１名で大丈夫なら１名で、２名が必要なら２名ということになっちゃうかもしれませんが、あまりはっきり最初から１名なら１名、２名なら２名というふうに決めないで、視察の実態に即した形で事務局としてお考えいただいて、どうしても２名が必要だということになれば、２名でいいし、今回は１名で十分対応可能だということになれば１名でもいいと思います。最初から１名だとか２名だとかに限定しなくてもいいような気もするんですけれども、ただ、こちら側としては２名おられたほうがいいのかなという、そんな気もします。\n視察のあり方については、さっき言われたように、目的を明確にして、これは当然そういうことで行われるわけですから、じゃ、今すぐどうこうというのではなく、私個人的には、視察地の候補をしっかりと決めていけばいいのではないでしょうか。"},{"i":152,"speaker":"南委員長","text":"理事者については、１名ということで、この数字はもう決定ということになっているんです。前議長と区長との間でそういうことになったというふうに報告を聞いております。"},{"i":153,"speaker":"菊地委員","text":"視察の目的というところで、私は２年目ですのでよくわからないんですが、もしかしたら、視察に行く場所がない、必要がないと言って、委員会として実際に行政視察に行かないという可能性をも含んでいるわけですよね。行政視察というものはね。さっきの話の続きみたいになっちゃいますけれども，こういう視察をしなくちゃいけないというのが、前面に出て初めて考え方そのものは、全般の委員会の１年間のテーマに基づいた必要な場所というのが、行政視察というのは、私としてはそういう考え方、だから区民委員会でこの１年間こういうことをやってみたい、それに基づいて、こういうところに行ってみたいという提案を、個人的に言えば、するわけですから、基本的には、前段に委員会の中で話されていた、区民委員会の１年間の、どこに軸足を置いていくのかというところが決まらないと、自分でもなかなか提案できない。去年は建設委員会でしたけれども、あそこへ行ってみたい、ここへ行ってみたいというのを出し合って、その流れで旅行先も決まったような感じがしますけれども、軸になる部分がどこにあるんだろうというのが、どうしてもまだ鮮明になり切れないと、なかなか提案し切れないなという問題があります。\nそれから、同行の部分について言いますと、個人で視察に何人かで、仲間うちで視察に行くときには、それぞれ自分で手配し、旅館を手配してやるわけですね。だから、それは、いなくても、もちろんできないことはないと思うんです。ただ、委員会でやる視察というのはそれなりに重みがあると思うんです。最終的にこういう報告書をつくり上げてというところまで、かなり重みを持ったものだと思いますので、実際に書記の仕事というのは、２回行ってきただけですから、どこまで大変なのかというのがちょっとわからないのですけれども、皆さんが今まで出されている意見も含めて、単純に１名にすればいいというものではないような気もしています。\n意見としては以上です。"},{"i":154,"speaker":"金高委員","text":"ここに区民委員会として、８つの課があるわけですけれども、例えばこれらの部分について全部の行政がそれぞれ持っているわけですね。品川区が地域に行って、その地域を見たときに、それぞれの地域でもって、例えばどれが出っ張って、どれが引っ込んでいるかという、そういうのがあるわけですね。そうした対象が我々の視察の大きな目的になってくるわけですね。ですから、どの程度云々ということも当然でしょうし、それは皆さんで決めなければいけない。それから、どの部署でそれをやるかということも決めなければいけないというふうに考えたときに、それをまず皆さんと絞り込んだ上でもって、それに見合う場所はどこだとか、それから、先ほど言ったように、費用の平準化ですか、委員長が発言しましたけれども、例えば近場だったら、近場での費用、あるいは泊まる宿なら泊まる宿の費用、もっと極端なことを言えば、私は一番最初北海道に行かせていただいたんですけれども、北海道は一番遠いわけですから当然費用がかかる。それぞれ委員会の目的、行く場所によって大きく変わってくるわけですから、それを平準化してどうこうというのはちょっと当てはまらない面があるんじゃないかという気がします。"},{"i":155,"speaker":"南委員長","text":"そういう意味で言ったんじゃないんです。"},{"i":156,"speaker":"石田副委員長","text":"理事者の方と、書記と、我々との出てくる費用が違う。それの標準化をどうするかということです。"},{"i":157,"speaker":"金高委員","text":"そっちのほうですか。要するに、視察の費用じゃなくて。私はちょっとそういうふうに思ったものだから、どうかなと思ったんです。それは理解しました。\nそういう意味で、費用の平準化は別としまして、それについてはこの区民委員会の８つのところ、例えば防災だったら、廃止ということは当然出てくるでしょうし、もっと極端なことを言えば、三宅島はどうだとか、そういったことだって考えられるわけです。だけど、違った意味において地域活動、あるいは産業振興だったら、産業振興でも、日本の全国を眺めて、どういう形でもって品川区の考え方でもって伸びているところがあるのか，あるいはだめなところはどうかとか、同じ産業振興でも、観光なのか、技術なのかという意味によって相当違うと思います。それをどういうふうに絞ってやるかということで、地域が決まってくると思います。ですから、まず今回はどれをテーマにするかというのを踏み込んでいけばいいんじゃないか。\n昨年、総務委員会のほうに所属させてもらったんですけれども、いつも大体１０月の終わりというふうに限定されていたのは，総務委員会はテーマは８月の終わりに実施した。それは皆さんの中でもって決めたわけですので、日にちを特定することも、当然全体の流れとしてはスケジュールではいいでしょうけれども、それにとらわれずに、別の日があるんだったら、それに基づいてやってもいいんじゃないかという気もいたします。"},{"i":158,"speaker":"藤原委員","text":"随行の書記については、経費という形だけ見ちゃうと、１人のほうがとなっちゃうと思うんですが、２名必要であるならば、私は２名でもいいと思います。\nあと、場所についてですが、場所ありきじゃなくして、各委員の方がこういうテーマの視察をしたいというのがあると思いますので、出していただいて、それから場所等は決めればいいと思います。\nあと、原委員からお話が出ましたが、そのテーマに沿って勉強会という話が出まして、私もまだ２回しか視察に行っていませんが、過去２回とも視察が終わった後に、行った場所についての、視察に行った後のすぐの委員会において、視察のところでどうだったという話す時間帯があると思ったんですが、何もなかったので、行く前にテーマについて時間をとって話すのもいいと思いますし、場所と離れるかもしれませんが，終わった後に視察についての反省、文章において報告書という形で、総務委員会の場合はまとめさせていただいたんですけれども、視察に行った後も何かあるといいなと思います。"},{"i":159,"speaker":"原委員","text":"さっきちょっと、視察をやるかやらないかという話にちょっと触れたんですけれども、その問題は違った時限で処理しなくちゃならないと思うんです。なぜかというと、５常任委員会がある中で、この委員会は視察をしない、この委員会は視察をするということになると、ばらつきの問題も出てくる。そこに予算もついてあるわけだから、それを執行をどうするかとか、いろんな話が出てくるので、それはやらないんじゃなくて、ほかの時点でやるか、やらないかという話し合いはしなければいけないと思います。\nまず、区民委員会としては視察は例年の中でやっていくという前向きの姿勢の中で皆さんで検討する。そういうことがプラスの思考じゃないかなと思います。これは私の意見ですけれども、やらないということは、やはりある意味のマイナス思考だと思うし、もしそれを論議するならば、違う時点で論議をしなければならないと思います。"},{"i":160,"speaker":"南委員長","text":"それでは、一応皆さんから出していただきまして、ありがとうございました。\nこれをどういうふうにまとめるということはしないで、このまま持ち込んで、委員長会に報告をしていきたいと思っています。"},{"i":161,"speaker":"石田副委員長","text":"差額のことは。"},{"i":162,"speaker":"南委員長","text":"それは理解してくださったというふうに思ったから。"},{"i":163,"speaker":"石田副委員長","text":"その処理をどうするかということは。全体で取り組んで、みんなで割って、それでいいかなという確認だけは。そういうことでいいかどうかという。"},{"i":164,"speaker":"南委員長","text":"それは現実的な問題になったときでいいんじゃないですか。"},{"i":165,"speaker":"原委員","text":"話を明らかにしておけばいいんじゃないですか。どうするかは、２人で。"},{"i":166,"speaker":"南委員長","text":"実は、午前中の話のときには、さっき整理して理解していただいたんですけれども、それぞれ具体的に言うと、委員、理事者、書記がそれぞれのところで交通費だとか、規定があって、出ますよね。だけど、金額が違うのが日当のところが違うんだそうです。同じホテルに泊まり、同じ食事をし、全く同じ行動をするわけですから、かかる費用も同じなわけですよね。ですから、そこのところで日当も全部プールして、予算額全体で、２泊３日の行政視察を賄うわけです。ですから、当然差があるところが現実なんだけれども、同じ費用がかかるから、もし差をつけちゃった場合に、そういうことはやめたいねという話をしたんです。具体的に今度のこれから取り組む視察かどういうふうになるかは、経費は全然、目的もまだはっきりしていない、行く場所もわからないですから、どういうふうになるかわかりませんけれども、しかし、足が出るようなことはしないで運営をしていきたいというふうに思ったので、そこのところを確認したんです。ですから、そういうふうにしていきたいというふうに思っております。\n報告書のやり方についても、意見を出していただきましたので、これについても報告をし、これから具体的になった段階でまた皆さんのご意見も伺いながら、いい報告になるように、効果のあるようにしていきたいと思っています。\n行政視察をするか、しないかの論議はまた別問題だと。それはそのとおりですから、そういうふうにしたいと思います。\nとりあえず今日のところの行政視察については、以上で、皆さんのご意見を伺ったということで、ありがとうございました。。\nでは、２９日の委員長会の結果については、またご報告をさせていただきます。\n以上をもちまして、今日の予定はすべて終了しましたので、区民委員会を閉会します。\n○午後５時０５分閉会"}]});
